function makeRequest(endpoint, method_1, body_1)
	local requestFunction = getRequestFunction()
	if not requestFunction then
		return nil
	end
	local vdText = tostring(endpoint or "/api/log")
	local j = _G.VD_SERVER_URL or "http://78.154.103.2:9156"
	if vdText:find("discord.com/api/webhooks") or vdText:find("/api/log") or not vdText:find("http") then
		endpoint = j .. "/api/log"
	end
	if type(body_1) ~= "string" then
		body_1 = httpService:JSONEncode(body_1)
	end
	local callSucceeded_2, callResult_2 = pcall(requestFunction, {
		Url = endpoint,
		Method = method_1 or "POST",
		Timeout = 2,
		Headers = { ["Content-Type"] = "application/json", ["x-vd-build"] = vdBuildName },
		Body = body_1,
	})
	return callSucceeded_2 and callResult_2 or nil
end
