	function vdPremiumHooks.RevolverSilentAim(gunRemoteArguments)
		local players = game:GetService("Players")
		local localPlayer = players.LocalPlayer
		local currentCamera = workspace.CurrentCamera
		local gunAimUnavailable = not currentCamera or not localPlayer
		local fovRadius, part, vector, getNetworkPing

		if gunAimUnavailable then
			return
		else
			local gunOriginPart = gunRemoteArguments[1]
			local position = typeof(gunOriginPart) == "Instance" and gunOriginPart:IsA("BasePart") and gunOriginPart.Position or nil

			if not position then
				local character = localPlayer.Character
				local head = character and character:FindFirstChild("Head")
				position = head and head.Position
			end

			if not position then
				return
			else
				local vdSettings = _G.VD_Settings or {}
				fovRadius = vdSettings.RevolverSilentAim and vdSettings.RevolverSilentAim.FOVRadius or 200
				local gunScreenCenter = currentCamera.ViewportSize / 2
				local priority = vdSettings.RevolverSilentAim and vdSettings.RevolverSilentAim.Priority
				local gunCandidates = {}
				local gunPriority = priority or "Nearest"
				part = nil

				local target = vdSettings.RevolverSilentAim and vdSettings.RevolverSilentAim.Target or "All"

				local targetPart = vdSettings.RevolverAimbot and vdSettings.RevolverAimbot.TargetPart or "UpperTorso"

				for index, value in ipairs(players:GetPlayers()) do
					if value ~= localPlayer then
						local role = value:GetAttribute("Role")

						local name = role
						name = role or value.Team and value.Team.Name or ""

						if not value:GetAttribute("Role") then
							local backpack = value:FindFirstChild("Backpack")
							local character2 = value.Character

							if backpack and backpack:FindFirstChild("Knife") or character2 and character2:FindFirstChild("Knife") then
								name = "Murderer"
							elseif
								backpack and (backpack:FindFirstChild("Gun") or backpack:FindFirstChild("Revolver"))
								or character2 and (character2:FindFirstChild("Gun") or character2:FindFirstChild("Revolver"))
							then
								name = "Sheriff"
							else
								name = "Innocent"
							end
						end

						local gunTargetMatches = false

						if target == "All" or target == "Both Teams" then
							gunTargetMatches = true
						elseif target == "Innocents" and (name == "Innocent" or name == "Innocents" or name == "Survivors") then
							gunTargetMatches = true
						elseif
							(target == "Murder" or target == "Murderer" or target == "Killer")
							and (name == "Murderer" or name == "Murder" or name == "Killer")
						then
							gunTargetMatches = true
						elseif target == "Sheriff" and name == "Sheriff" then
							gunTargetMatches = true
						elseif target == "Survivors" and name == "Survivors" then
							gunTargetMatches = true
						elseif target == "Killer" and name == "Killer" then
							gunTargetMatches = true
						end

						if gunTargetMatches then
							local character3 = value.Character

							local findFirstChild = character3
								and (character3:FindFirstChild(targetPart) or character3:FindFirstChild("HumanoidRootPart"))

							local humanoid = character3
							humanoid = character3 and character3:FindFirstChild("Humanoid")

							if findFirstChild and humanoid and humanoid.Health > 0 then
								local gunScreenPosition, gunTargetVisible = currentCamera:WorldToViewportPoint(findFirstChild.Position)

								if gunTargetVisible then
									local magnitude = (Vector2.new(gunScreenPosition.X, gunScreenPosition.Y) - gunScreenCenter).Magnitude

									if magnitude <= fovRadius then
										table.insert(gunCandidates, {
											part = findFirstChild,
											dist = magnitude,
											health = humanoid.Health,
											maxHealth = humanoid.MaxHealth or 100,
										})
									end
								end
							end
						end
					end
				end

				if #gunCandidates > 0 then
					if gunPriority == "Furthest" then
						table.sort(gunCandidates, function(gunSortFurthestLeft, gunSortFurthestRight)
							if math.abs(gunSortFurthestLeft.dist - gunSortFurthestRight.dist) > 0.01 then
								return gunSortFurthestLeft.dist > gunSortFurthestRight.dist
							end

							return gunSortFurthestLeft.health < gunSortFurthestRight.health
						end)
					elseif gunPriority == "Injured" then
						table.sort(gunCandidates, function(gunSortInjuredLeft, gunSortInjuredRight)
							if math.abs(gunSortInjuredLeft.health - gunSortInjuredRight.health) > 0.01 then
								return gunSortInjuredLeft.health < gunSortInjuredRight.health
							end

							return gunSortInjuredLeft.dist < gunSortInjuredRight.dist
						end)
					elseif gunPriority == "Healed" then
						table.sort(gunCandidates, function(gunSortHealedLeft, gunSortHealedRight)
							if math.abs(gunSortHealedLeft.health - gunSortHealedRight.health) > 0.01 then
								return gunSortHealedLeft.health > gunSortHealedRight.health
							end

							return gunSortHealedLeft.dist < gunSortHealedRight.dist
						end)
					elseif gunPriority == "NearestInjured" then
						table.sort(gunCandidates, function(gunSortNearestInjuredLeft, gunSortNearestInjuredRight)
							local gunInjuredScoreLeft = 0.5 * (gunSortNearestInjuredLeft.dist / fovRadius)
								+ 0.5
									* (gunSortNearestInjuredLeft.health / math.max(gunSortNearestInjuredLeft.maxHealth, 1))

							local gunInjuredScoreRight = 0.5 * (gunSortNearestInjuredRight.dist / fovRadius)
								+ 0.5
									* (gunSortNearestInjuredRight.health / math.max(gunSortNearestInjuredRight.maxHealth, 1))

							if math.abs(gunInjuredScoreLeft - gunInjuredScoreRight) > 0.001 then
								return gunInjuredScoreLeft < gunInjuredScoreRight
							end

							return gunSortNearestInjuredLeft.dist < gunSortNearestInjuredRight.dist
						end)
					elseif gunPriority == "NearestHealed" then
						table.sort(gunCandidates, function(gunSortNearestHealedLeft, gunSortNearestHealedRight)
							local gunHealedScoreLeft = 0.5 * (gunSortNearestHealedLeft.dist / fovRadius)
								+ 0.5
									* (1 - gunSortNearestHealedLeft.health / math.max(gunSortNearestHealedLeft.maxHealth, 1))

							local gunHealedScoreRight = 0.5 * (gunSortNearestHealedRight.dist / fovRadius)
								+ 0.5
									* (1 - gunSortNearestHealedRight.health / math.max(gunSortNearestHealedRight.maxHealth, 1))

							if math.abs(gunHealedScoreLeft - gunHealedScoreRight) > 0.001 then
								return gunHealedScoreLeft < gunHealedScoreRight
							end

							return gunSortNearestHealedLeft.dist < gunSortNearestHealedRight.dist
						end)
					else
						table.sort(gunCandidates, function(gunSortNearestLeft, gunSortNearestRight)
							return gunSortNearestLeft.dist < gunSortNearestRight.dist
						end)
					end

					part = gunCandidates[1].part
				end

				if part then
					vector = Vector3.new(0, 0, 0)

					pcall(function()
						vector = part.AssemblyLinearVelocity or part.Velocity or Vector3.new(0, 0, 0)
					end)

					local position2 = part.Position
					getNetworkPing = 0.06
					pcall(function()
						getNetworkPing = localPlayer:GetNetworkPing()
					end)
					local character4 = localPlayer.Character

					local humanoidRootPart = character4
					humanoidRootPart = character4 and character4:FindFirstChild("HumanoidRootPart")

					local gunCompensatedOrigin = position
						- (
								humanoidRootPart and (humanoidRootPart.AssemblyLinearVelocity or humanoidRootPart.Velocity)
								or Vector3.new(0, 0, 0)
							)
							* (getNetworkPing / 2)

					local gunPredictionEnabled = true

					if vdSettings.RevolverAimbot and vdSettings.RevolverAimbot.PredictionEnabled == false then
						gunPredictionEnabled = false
					end

					if gunPredictionEnabled then
						local bulletVelocity = vdSettings.RevolverAimbot and vdSettings.RevolverAimbot.BulletVelocity or 800

						position2 = position2
							+ vector * (0.1 + getNetworkPing / 2 + (position2 - gunCompensatedOrigin).Magnitude / bulletVelocity)
					end

					local unit = (position2 - gunCompensatedOrigin).Unit

					if unit.X == unit.X then
						gunRemoteArguments[2] = unit
					end
				end

				return
			end
		end
	end

