	function vdPremiumHooks.AntiWiggle()
		local players3 = game:GetService("Players")
		local localPlayer3 = players3.LocalPlayer

		if not localPlayer3 then
			return
		end

		if
			localPlayer3:GetAttribute("IsCarrying") == true
			or localPlayer3.Character and localPlayer3.Character:GetAttribute("IsCarrying") == true
		then
			local carriedPlayer = nil

			for index3, value3 in ipairs(players3:GetPlayers()) do
				if value3 ~= localPlayer3 then
					local character7 = value3.Character

					if value3:GetAttribute("IsCarried") == true or character7 and character7:GetAttribute("IsCarried") == true then
						carriedPlayer = value3
						break
					end
				end
			end

			if carriedPlayer then
				local character8 = carriedPlayer.Character

				local remainingCarryTime = carriedPlayer:GetAttribute("RemainingCarryTime")
					or character8 and character8:GetAttribute("RemainingCarryTime")
					or localPlayer3:GetAttribute("RemainingCarryTime")
					or localPlayer3.Character and localPlayer3.Character:GetAttribute("RemainingCarryTime")

