	function vdPremiumHooks.InstantBandage(bandagePlayer, bandageNotify)
		local character9 = bandagePlayer.Character
		local humanoid4 = character9 and character9:FindFirstChildOfClass("Humanoid")
		local bandage, fire

		if not humanoid4 then
