				else
					local replicatedStorage2 = game:GetService("ReplicatedStorage")
					local remotes = replicatedStorage2:FindFirstChild("Remotes")

					local items = remotes
					items = remotes and remotes:FindFirstChild("Items")

					local bandage3 = items
					bandage3 = items and items:FindFirstChild("Bandage")

					fire = bandage3 and bandage3:FindFirstChild("Fire")

