	function vdPremiumHooks.CancelGen(genPlayer, cachedGenModels, genNotify)
		if genNotify then
			genNotify("Generator Buff", "Attempting to buff generator...", "info")
		end

		task.spawn(function()
			local genBuffOk, genBuffError = pcall(function()
				local character10 = genPlayer.Character
				local humanoidRootPart3 = character10 and character10:FindFirstChild("HumanoidRootPart")

				if not humanoidRootPart3 then
					if genNotify then
						genNotify("Generator Buff", "Character HumanoidRootPart not found!", "error")
					end

					return
				else
					local function getGeneratorBasePart(genModel)
						if genModel:IsA("Model") then
							return genModel.PrimaryPart or genModel:FindFirstChildWhichIsA("BasePart")
						end

						return genModel:FindFirstChildWhichIsA("BasePart")
					end

					local generatorCandidates = {}
					local map = workspace:FindFirstChild("Map")
					local generatorContainers = {}

					if map then
						local generators = map:FindFirstChild("Generators")
						local gens = map:FindFirstChild("Gens")

						if generators then
							table.insert(generatorContainers, generators)
						end

						if gens then
							table.insert(generatorContainers, gens)
						end
					end

					for index11, value11 in ipairs(generatorContainers) do
						for index12, value12 in ipairs(value11:GetChildren()) do
							local isExactGeneratorName = value12.Name == "Generator"
							local isGeneratorName = isExactGeneratorName

							if not isExactGeneratorName then
								local name2 = value12.Name
								isGeneratorName = string.find(name2:lower(), "generator")
							end

							if isGeneratorName then
								table.insert(generatorCandidates, value12)
							end
						end
					end

					if #generatorCandidates == 0 and cachedGenModels then
						for index13, value13 in ipairs(cachedGenModels) do
							if value13 and value13.Parent then
								table.insert(generatorCandidates, value13)
							end
						end
					end

					if #generatorCandidates == 0 then
						for index14, value14 in ipairs(workspace:GetDescendants()) do
							if value14.Name == "Generator" then
								table.insert(generatorCandidates, value14)
							end
						end
					end

					if #generatorCandidates == 0 then
						if genNotify then
							genNotify("Generator Buff", "No generators found in map!", "error")
						end

						return
					else
						local nearestGenerator = nil
						local huge = math.huge

						for index15, value15 in ipairs(generatorCandidates) do
							local generatorPart = getGeneratorBasePart(value15)

							if generatorPart then
								local magnitude3 = (generatorPart.Position - humanoidRootPart3.Position).Magnitude

								if magnitude3 < huge then
									nearestGenerator = value15
									huge = magnitude3
								end
							end
						end

						if not nearestGenerator or huge > 15 then
							local generatorDistanceLabel = nearestGenerator and string.format("%.1f studs", huge) or "N/A"

							if genNotify then
								genNotify("Generator Buff", "No generator within 15 studs! (" .. generatorDistanceLabel .. ")", "error")
							end

							return
						else
							local generatorPoints = {}

							for index16, value16 in ipairs(nearestGenerator:GetChildren()) do
								local name3 = value16.Name

								if string.find(name3:lower(), "generatorpoint") then
									table.insert(generatorPoints, value16)
								end
							end

							table.sort(generatorPoints, function(genPointLeft, genPointRight)
								return genPointLeft.Name < genPointRight.Name
							end)

							if #generatorPoints == 0 then
								if genNotify then
									genNotify("Generator Buff", "No generator points resolved!", "error")
								end

								return
							else
								local replicatedStorage7 = game:GetService("ReplicatedStorage")
								local remotes6 = replicatedStorage7:FindFirstChild("Remotes")

								local generator = remotes6
								generator = remotes6 and remotes6:FindFirstChild("Generator")

								local repairEvent = generator
								repairEvent = generator and generator:FindFirstChild("RepairEvent")

								if not repairEvent then
									repairEvent = replicatedStorage7:FindFirstChild("RepairEvent", true)
								end

								if not repairEvent then
									if genNotify then
										genNotify("Generator Buff", "RepairEvent remote not found!", "error")
									end

									return
								else
									local generatorPointCount = #generatorPoints

									if generatorPointCount == 2 then
										local generatorFirstPoint = generatorPoints[1]
										repairEvent:FireServer(generatorPoints[2], true)
										task.wait(0.2)
										repairEvent:FireServer(generatorFirstPoint, true)
										task.wait(0.2)
										repairEvent:FireServer(generatorFirstPoint, false)
									else
										local generatorLastPoint = generatorPoints[generatorPointCount]
										local generatorLastIndex = generatorPointCount - 1
										local count4 = 0

										while true do
											count4 = 1 + count4

											if not (count4 <= generatorLastIndex) then
												break
											end

											local generatorPointIndex = count4
											repairEvent:FireServer(generatorPoints[generatorPointIndex], true)
											task.wait(0.2)
											repairEvent:FireServer(generatorLastPoint, true)
											task.wait(0.2)
											repairEvent:FireServer(generatorLastPoint, false)

											if generatorPointIndex < generatorPointCount - 1 then
												task.wait(0.2)
											end
										end
									end

									if genNotify then
										genNotify("Generator Buff", "Successfully applied generator buff!", "success")
									end

									return
								end
							end
						end
					end
				end
			end)

			if not genBuffOk and genNotify then
				genNotify("Generator Buff", "Critical Error: " .. tostring(genBuffError), "error")
			end
		end)
	end

	function vdPremiumHooks.AlwaysFastVault_OnAnim(slowVaultTrack, fastVaultTrack, vaultAnimationSettings)
