			local lower2 = tostring(slowVaultTrack.Animation and slowVaultTrack.Animation.AnimationId or ""):lower()
			local lower3 = (slowVaultTrack.Name or ""):lower()

			if lower2:find("126081405469607") or lower3:find("walkingvault") then
				pcall(function()
					slowVaultTrack:Stop(0)
				end)

