	function vdPremiumHooks.AlwaysFastVault_OnInput(vaultInput, vaultPlayer, findNearbyVault, vaultInputSettings)
		if not (vaultInputSettings and vaultInputSettings.AlwaysFastVault) then
			return
		end

		local unit2, character11

		if vaultInput.KeyCode == Enum.KeyCode.E or vaultInput.KeyCode == Enum.KeyCode.Space then
			character11 = vaultPlayer.Character
			local humanoidRootPart4 = character11 and character11:FindFirstChild("HumanoidRootPart")

			if humanoidRootPart4 and findNearbyVault then
				local nearbyVault = findNearbyVault(humanoidRootPart4.Position)

				if nearbyVault then
					local vaultDirection = nearbyVault.Position - humanoidRootPart4.Position
					local vector4 = Vector3.new(vaultDirection.X, 0, vaultDirection.Z)

					if vector4.Magnitude > 0.05 then
						unit2 = vector4.Unit
					else
						local lookVector = humanoidRootPart4.CFrame.LookVector
						unit2 = Vector3.new(lookVector.X, 0, lookVector.Z).Unit
					end

					local dot = humanoidRootPart4.CFrame.LookVector:Dot(unit2)

					if not (humanoidRootPart4.AssemblyLinearVelocity.Magnitude >= 13 and dot >= 0.7) then
						pcall(function()
							character11:SetAttribute("Sprinting", true)
							character11:SetAttribute("IsRunning", true)
						end)

						humanoidRootPart4.CFrame = CFrame.new(humanoidRootPart4.Position, humanoidRootPart4.Position + unit2)

						humanoidRootPart4.AssemblyLinearVelocity = unit2 * 22
					end
				end
			end
		end
	end

	function vdPremiumHooks.AlwaysFastVault_OnNamecall(
		vaultRemote,
		vaultMethod,
		vaultArguments,
		vaultCaller,
		vaultStartEvent,
		vaultEndEvent,
		vaultCallSettings
	)
		if not (vaultCallSettings and vaultCallSettings.AlwaysFastVault) then
			return
		end

		local character12

		if (vaultMethod == "FireServer" or vaultMethod == "InvokeServer") and typeof(vaultRemote) == "Instance" then
			if vaultRemote.Name == "VaultEvent" then
				if vaultArguments[2] == false then
					vaultArguments[2] = true
					character12 = vaultCaller.Character

					if character12 then
						pcall(function()
							character12:SetAttribute("Sprinting", true)
							character12:SetAttribute("IsRunning", true)
						end)
					end

					if vaultStartEvent and character12 then
						pcall(function()
							vaultStartEvent:FireServer(character12)
						end)
					end

					if vaultEndEvent then
						pcall(function()
							vaultEndEvent:FireServer()
						end)
					end
				end
			end
		end
	end

	function vdPremiumHooks.CustomGenSound(soundGenerator, generatorSoundId, generatorVolume)
		if not soundGenerator or not soundGenerator:IsA("Model") then
			return
		else
			local function normalizeGeneratorSound(generatorSoundInput)
				if not generatorSoundInput or generatorSoundInput == "" then
					return "rbxassetid://124429695332529"
				elseif type(generatorSoundInput) == "number" then
					return "rbxassetid://" .. tostring(generatorSoundInput)
				else
					local gsub2 = tostring(generatorSoundInput):gsub("%s+", "")

					if gsub2:find("^rbxassetid://") or gsub2:find("^http") or gsub2:find("^assetgame") then
						return gsub2
					else
						local d = gsub2:match("%d+")

						if d then
							return "rbxassetid://" .. d
						end

						return gsub2
					end
				end
			end

			local normalizedGeneratorSound = normalizeGeneratorSound(generatorSoundId)
			local volume = generatorVolume or 1
			local hitBox = soundGenerator:FindFirstChild("HitBox") or soundGenerator:FindFirstChild("Hitbox")

			if hitBox then
				local done = hitBox:FindFirstChild("Done")

				if done and done:IsA("Sound") then
					if done.SoundId ~= normalizedGeneratorSound then
						done.SoundId = normalizedGeneratorSound
					end

					done.Volume = volume
				end
			end

			return
		end
	end

	function vdPremiumHooks.AutoFleeKiller(
		fleeCharacter,
		fleeRoot,
		killerPosition,
		fleeGenerators,
		getFleeGenPart,
		isFleeGenComplete,
		isFleeGenPaused,
		getFleeGenPoint,
