							spoofNearestGenerator = value23
							huge3 = magnitude6
						end
					end
				end

				if not spoofNearestGenerator or huge3 > 35 then
					local spoofDistanceLabel = spoofNearestGenerator and string.format("%.1f studs", huge3) or "N/A"

					if spoofNotify then
						spoofNotify("Manual Spoof", "No generator within 35 studs! (" .. spoofDistanceLabel .. ")", "error")
					end

					return
				else
					local spoofGeneratorPoints = {}

					for index24, value24 in ipairs(spoofNearestGenerator:GetChildren()) do
						local name5 = value24.Name
						local spoofIsGeneratorPoint = string.find(name5:lower(), "generatorpoint")
						local spoofIsPoint = spoofIsGeneratorPoint

						if not spoofIsGeneratorPoint then
							local name6 = value24.Name
							spoofIsPoint = string.find(name6:lower(), "point")
						end

						if spoofIsPoint then
							table.insert(spoofGeneratorPoints, value24)
						end
					end

					function getSpoofPointPosition(spoofGenPoint)
						if spoofGenPoint:IsA("BasePart") then
							return spoofGenPoint.Position
						elseif spoofGenPoint:IsA("Model") then
							return spoofGenPoint:GetPivot().Position
						else
							local basePart = spoofGenPoint:FindFirstChildWhichIsA("BasePart")

							if basePart then
								return basePart.Position
							end

							return spoofGenPoint.Parent and spoofGenPoint.Parent:IsA("Model") and spoofGenPoint.Parent:GetPivot().Position
								or Vector3.zero
						end
					end

					table.sort(spoofGeneratorPoints, function(spoofLeftPoint, spoofRightPoint)
						return (getSpoofPointPosition(spoofLeftPoint) - humanoidRootPart5.Position).Magnitude
							< (getSpoofPointPosition(spoofRightPoint) - humanoidRootPart5.Position).Magnitude
					end)

					local replicatedStorage8 = game:GetService("ReplicatedStorage")
					local remotes7 = replicatedStorage8:FindFirstChild("Remotes")

					local generator2 = remotes7
					generator2 = remotes7 and remotes7:FindFirstChild("Generator")

					local repairEvent2 = generator2
					repairEvent2 = generator2 and generator2:FindFirstChild("RepairEvent")

					if not repairEvent2 then
						repairEvent2 = replicatedStorage8:FindFirstChild("RepairEvent", true)
					end

					if not repairEvent2 then
						for index25, value25 in ipairs(replicatedStorage8:GetDescendants()) do
							if value25:IsA("RemoteEvent") and (value25.Name == "RepairEvent" or value25.Name == "Repair") then
								repairEvent2 = value25
								break
							end
						end
					end

					if repairEvent2 and #spoofGeneratorPoints > 0 then
						local spoofFirstPoint = spoofGeneratorPoints[1]
						local spoofLastPoint = #spoofGeneratorPoints > 1 and spoofGeneratorPoints[#spoofGeneratorPoints] or nil
						repairEvent2:FireServer(spoofFirstPoint, true)
						task.wait(0.1)
						repairEvent2:FireServer(spoofFirstPoint, true)
						task.wait(0.1)

						if spoofLastPoint and spoofLastPoint ~= spoofFirstPoint then
							repairEvent2:FireServer(spoofLastPoint, false)
						end

						if spoofNotify then
							spoofNotify("Manual Spoof", "Successfully spoofed +1 player on generator!", "success")
						end
					elseif spoofNotify then
						spoofNotify("Manual Spoof", "Could not find generator repair event/points!", "error")
					end

					return
				end
			end
		end
	end

	function vdPremiumHooks.NoSkillChecks(skillCheckParent, removedSkillChecks)
