		end
	end

	function vdPremiumHooks.RunSpearAimbot(spearAimContext)
		local char, localPlayer4, camera, userInputService, players4, settings, spearChargeStart, specialSpearSpeed, normalSpearSpeed, specialSpearGravity, normalSpearGravity, getSmoothedVelocity, solveProjectileAim, isMouseButtonPressed, key, root

		if not spearAimContext then
			return
		else
			char = spearAimContext.char
			localPlayer4 = spearAimContext.localPlayer
			camera = spearAimContext.camera
			local isMobile = spearAimContext.isMobile
			userInputService = spearAimContext.UserInputService
			players4 = spearAimContext.Players
			settings = spearAimContext.Settings
			spearChargeStart = spearAimContext.spearChargeStart
			specialSpearSpeed = spearAimContext.specialSpearSpeed
			normalSpearSpeed = spearAimContext.normalSpearSpeed
			specialSpearGravity = spearAimContext.specialSpearGravity
			normalSpearGravity = spearAimContext.normalSpearGravity
			local sortCandidatesByPriority = spearAimContext.sortCandidatesByPriority
			getSmoothedVelocity = spearAimContext.getSmoothedVelocity
			solveProjectileAim = spearAimContext.solveProjectileAim
			local getTarget = spearAimContext.getTarget
			local setTarget = spearAimContext.setTarget

			if not settings or not settings.SpearAimbot or not settings.SpearAimbot.Enabled then
				if setTarget then
					setTarget(nil)
				end

				return
			else
				local spearCharacterMode = char
				local spearModeEnabled = false

				if char then
					spearCharacterMode = char:GetAttribute("spearmode") == true
				end

				if spearCharacterMode then
					spearModeEnabled = true
				elseif localPlayer4 and localPlayer4:GetAttribute("spearmode") == true then
					spearModeEnabled = true
				end

				if not spearModeEnabled then
					if setTarget then
						setTarget(nil)
					end

					return
				end

				isMouseButtonPressed = false

				if isMobile then
					isMouseButtonPressed = true
				else
					key = settings.SpearAimbot.Key or "MouseButton2"

					if key == "MouseButton2" then
						isMouseButtonPressed = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
					elseif key == "MouseButton1" then
						isMouseButtonPressed = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
					else
						pcall(function()
							isMouseButtonPressed = userInputService:IsKeyDown(Enum.KeyCode[key])
						end)
					end
				end

				if not isMouseButtonPressed then
					if setTarget then
						setTarget(nil)
					end

					return
				elseif not camera then
					return
				else
					local getMouseLocation = userInputService:GetMouseLocation()

					if isMobile then
						getMouseLocation = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
					end

					local radius = settings.SpearAimbot.Radius or 150
					local priority3 = settings.SpearAimbot.Priority or "Nearest"
					root = getTarget and getTarget()

					if
						not root
						or not root.Parent
						or not root.Parent:FindFirstChildOfClass("Humanoid")
						or root.Parent:FindFirstChildOfClass("Humanoid").Health <= 0
					then
						local team = localPlayer4 and localPlayer4.Team
						local spearAimCandidates = {}

						for index27, value27 in ipairs(players4:GetPlayers()) do
							if value27 ~= localPlayer4 and not (team and value27.Team == team) then
								local character14 = value27.Character

								local humanoid5 = character14
								humanoid5 = character14 and character14:FindFirstChildOfClass("Humanoid")

								local findFirstChild2 = character14
								local targetPart2 = settings.SpearAimbot.TargetPart or "UpperTorso"

								if character14 then
									findFirstChild2 = character14:FindFirstChild(targetPart2)
										or character14:FindFirstChild("UpperTorso")
										or character14:FindFirstChild("Torso")
										or character14:FindFirstChild("HumanoidRootPart")
								end

								if character14 and humanoid5 and humanoid5.Health > 0 and findFirstChild2 then
									local spearAimScreenPosition, spearAimTargetVisible = camera:WorldToViewportPoint(findFirstChild2.Position)

									if spearAimTargetVisible then
										local magnitude7 = (Vector2.new(spearAimScreenPosition.X, spearAimScreenPosition.Y) - getMouseLocation).Magnitude

										if magnitude7 <= radius then
											table.insert(spearAimCandidates, {
												root = findFirstChild2,
												dist = magnitude7,
												health = humanoid5.Health,
												maxHealth = math.max(humanoid5.MaxHealth, 1),
											})
										end
									end
								end
							end
						end

						local spearAimBestCandidate = sortCandidatesByPriority
						spearAimBestCandidate = sortCandidatesByPriority and sortCandidatesByPriority(spearAimCandidates, priority3, radius)

						root = spearAimBestCandidate and spearAimBestCandidate.root or nil

						if setTarget then
							setTarget(root)
						end
					end

					if root and char then
						pcall(function()
							local parent = root.Parent

							local humanoidRootPart6 = parent:FindFirstChild("HumanoidRootPart")
								or parent.PrimaryPart
								or parent:FindFirstChild("Torso")
								or parent:FindFirstChild("UpperTorso")

							local getNetworkPing2

							if humanoidRootPart6 then
								local head2 = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")

								local position5 = camera.CFrame.Position

								if head2 then
									position5 = head2.CFrame:PointToWorldSpace((Vector3.new(1.35, 0.34, -2.51)))
								end

								local position6 = root.Position
								local assemblyLinearVelocity = humanoidRootPart6.AssemblyLinearVelocity
								local getPlayerFromCharacter2 = players4:GetPlayerFromCharacter(parent)

								local spearAimTargetVelocity = getPlayerFromCharacter2
										and getSmoothedVelocity
										and getSmoothedVelocity(getPlayerFromCharacter2, assemblyLinearVelocity)
									or assemblyLinearVelocity

								getNetworkPing2 = 0.04
								pcall(function()
									getNetworkPing2 = localPlayer4:GetNetworkPing()
								end)
								local spearAimPredictedPosition = position6 + spearAimTargetVelocity * (getNetworkPing2 + 0.05)
								local vector5 = Vector3.new(0, 0, 0)
								local humanoid6 = parent:FindFirstChildOfClass("Humanoid")

								if humanoid6 and humanoid6.FloorMaterial == Enum.Material.Air then
									vector5 = Vector3.new(0, -workspace.Gravity, 0)
								end

								local isSpecialSpear = char:GetAttribute("special") == true
								local speed = settings.SpearAimbot.Speed or 150
								local gravity = settings.SpearAimbot.Gravity or 98
								local spearAimSpeed = speed
								local spearAimGravity = gravity

								if speed == 150 then
									spearAimSpeed = isSpecialSpear and specialSpearSpeed or normalSpearSpeed
								elseif isSpecialSpear then
									spearAimSpeed = speed * 1.1333333333333
								end

								if gravity == 98 then
									spearAimGravity = isSpecialSpear and specialSpearGravity or normalSpearGravity
								elseif isSpecialSpear then
									spearAimGravity = gravity
								end

								local spearChargeDuration = tick() - (spearChargeStart or tick())
								local spearMinimumSpeed = spearAimSpeed * 0.7333
								local spearChargedSpeed = spearMinimumSpeed
									+ (spearAimSpeed - spearMinimumSpeed) * math.clamp(spearChargeDuration / 1, 0, 1)

								if solveProjectileAim then
									local spearAimDirection, spearAimPosition = solveProjectileAim(
										position5,
										spearAimPredictedPosition,
										spearAimTargetVelocity,
										vector5,
										spearChargedSpeed,
										spearAimGravity
									)
									local humanoidRootPart7 = char:FindFirstChild("HumanoidRootPart")

									if humanoidRootPart7 then
										humanoidRootPart7.CFrame = CFrame.new(
											humanoidRootPart7.Position,
											(Vector3.new(spearAimPosition.X, humanoidRootPart7.Position.Y, spearAimPosition.Z))
										)
									end

									local cframe = CFrame.lookAt(
										camera.CFrame.Position,
										position5 + spearAimDirection * (spearAimPosition - position5).Magnitude
									)

									local smoothness = settings.SpearAimbot.Smoothness or 0.05

									if smoothness <= 0 then
										camera.CFrame = cframe
									else
										camera.CFrame = camera.CFrame:Lerp(cframe, smoothness)
									end
								end
							end
						end)
					end

					return
				end
			end
		end
	end

	function vdPremiumHooks.SimulateParryAnimation(parryPlayer, parryNotify)
		local character15

		if not parryPlayer then
			return
		else
			character15 = parryPlayer.Character
			local humanoid7 = character15 and character15:FindFirstChildOfClass("Humanoid")
			local animator = humanoid7 and humanoid7:FindFirstChildOfClass("Animator")

			if humanoid7 and animator then
				task.spawn(function()
					local parryAnimationId = "109133187196613"

					pcall(function()
						local findFirstChild3 = workspace:FindFirstChild(parryPlayer.Name)

						local parryingDagger = findFirstChild3 and findFirstChild3:FindFirstChild("Parrying Dagger")

						local main = parryingDagger and parryingDagger:FindFirstChild("Main")

						if main then
							local parry = main:FindFirstChild("parry")

							if parry and parry:IsA("Sound") and parry.SoundId == "rbxassetid://108343313427067" then
								parryAnimationId = "126894569253341"
							end

							local parried = main:FindFirstChild("parried")

							if parried and parried:IsA("Sound") and parried.SoundId == "rbxassetid://110870555206505" then
								parryAnimationId = "123307242865945"
							end
						end
					end)

					local animation = Instance.new("Animation")
					animation.AnimationId = "rbxassetid://" .. parryAnimationId

					local loadAnimation = animator:LoadAnimation(animation)
					local walkSpeed = humanoid7.WalkSpeed
					local jumpPower = humanoid7.JumpPower
					local jumpHeight = humanoid7.JumpHeight

					humanoid7.WalkSpeed = 0
					humanoid7.JumpPower = 0
					humanoid7.JumpHeight = 0

					local humanoidRootPart8 = character15:FindFirstChild("HumanoidRootPart")

					if humanoidRootPart8 then
						humanoidRootPart8.Anchored = true
					end

					local getControls

					pcall(function()
						getControls = require(parryPlayer.PlayerScripts:WaitForChild("PlayerModule")):GetControls()
						getControls:Disable()
					end)

					loadAnimation:Play()
					local parryAnimationStopped = false

					local connect

					connect = loadAnimation.Stopped:Connect(function()
						parryAnimationStopped = true

						if connect then
							connect:Disconnect()
						end
					end)

					local parryStartTime = tick()

					while not parryAnimationStopped and tick() - parryStartTime < 5 and humanoid7 and humanoid7.Parent do
						task.wait()
					end

					if humanoid7 and humanoid7.Parent then
						humanoid7.WalkSpeed = walkSpeed
						humanoid7.JumpPower = jumpPower
						humanoid7.JumpHeight = jumpHeight
					end

					if humanoidRootPart8 and humanoidRootPart8.Parent then
						humanoidRootPart8.Anchored = false
					end

					if getControls then
						pcall(function()
							getControls:Enable()
						end)
					end
				end)
			end

			return
		end
	end

	function vdPremiumHooks.ApplyCustomSpeedKeybind(speedSlot, speedSettings, speedControls, saveSpeedSettings, speedNotify)
		if not speedSettings then
			return
		end

		local selectedSpeed = tonumber(speedSettings["CustomSpeed" .. tostring(speedSlot)]) or 1

		if speedSettings.SpeedBoostEnabled and math.abs((speedSettings.SpeedBoost or 1) - selectedSpeed) < 0.005 then
			speedSettings.SpeedBoostEnabled = false

			if speedControls and speedControls.SpeedBoostEnabled and speedControls.SpeedBoostEnabled.setValue then
				pcall(function()
					speedControls.SpeedBoostEnabled.setValue(false, false)
				end)
			end

			if saveSpeedSettings then
				pcall(saveSpeedSettings)
			end

			if speedNotify then
				speedNotify("Speed Boost", "Speed Boost toggled OFF!", "warning")
			end

			return
		end

		speedSettings.SpeedBoost = selectedSpeed
		speedSettings.SpeedBoostEnabled = true

		if speedControls then
			if speedControls.SpeedBoost and speedControls.SpeedBoost.setValue then
				pcall(function()
					speedControls.SpeedBoost.setValue(selectedSpeed, false)
				end)
			end

			if speedControls.SpeedBoostEnabled and speedControls.SpeedBoostEnabled.setValue then
				pcall(function()
					speedControls.SpeedBoostEnabled.setValue(true, false)
				end)
			end
		end

		if saveSpeedSettings then
			pcall(saveSpeedSettings)
		end

		if speedNotify then
			speedNotify(
				"Speed Boost [Slot " .. tostring(speedSlot) .. "]",
				"Custom speed set to " .. string.format("%.2f", selectedSpeed) .. "x!",
				"success"
			)
		end
	end

