		local function downloadDbdSoundResource(dbdSoundUrl)
			local dbdSoundRequest = syn and syn.request or http and http.request or http_request or fluxus and fluxus.request or request

			local dbdSoundGetResult, dbdSoundGetOk, dbdSoundGetStatus

			if dbdSoundRequest then
				local dbdSoundRequestOk, dbdSoundResponse = pcall(dbdSoundRequest, { Url = dbdSoundUrl, Method = "GET" })

				if dbdSoundRequestOk and type(dbdSoundResponse) == "table" then
					local body = dbdSoundResponse.Body or dbdSoundResponse.body or dbdSoundResponse.response
					local statusCode = dbdSoundResponse.StatusCode or dbdSoundResponse.status_code or dbdSoundResponse.Status or 200

					if body and #body > 500 and (statusCode == 200 or statusCode == 0) then
						return body
					end
				end

				dbdSoundGetOk, dbdSoundGetResult = pcall(function()
					return game:HttpGet(dbdSoundUrl)
				end)

				dbdSoundGetStatus = dbdSoundGetOk
				dbdSoundGetStatus = dbdSoundGetOk and dbdSoundGetResult and #dbdSoundGetResult > 500

				if dbdSoundGetStatus then
					return dbdSoundGetResult
				else
					local dbdSoundHttpOk, dbdSoundHttpBody = pcall(function()
						return game:HttpGet(dbdSoundUrl, true)
					end)

					if dbdSoundHttpOk and dbdSoundHttpBody and #dbdSoundHttpBody > 500 then
						return dbdSoundHttpBody
					end

					return nil
				end
			else
				dbdSoundGetOk, dbdSoundGetResult = pcall(function()
					return game:HttpGet(dbdSoundUrl)
				end)

				dbdSoundGetStatus = dbdSoundGetOk
				dbdSoundGetStatus = dbdSoundGetOk and dbdSoundGetResult and #dbdSoundGetResult > 500

				if dbdSoundGetStatus then
					return dbdSoundGetResult
				else
					local dbdFallbackOk, dbdFallbackBody = pcall(function()
						return game:HttpGet(dbdSoundUrl, true)
					end)

					if dbdFallbackOk and dbdFallbackBody and #dbdFallbackBody > 500 then
						return dbdFallbackBody
					end

					return nil
				end
			end
		end

		local function isDbdSoundCacheValid(dbdSoundFile)
			if not (isfile and readfile) or not isfile(dbdSoundFile) then
				return false
			else
				local dbdReadSoundOk, dbdReadSoundBody = pcall(readfile, dbdSoundFile)

				if not dbdReadSoundOk or not dbdReadSoundBody or #dbdReadSoundBody < 5000 then
					return false
				else
					local lower4 = dbdReadSoundBody:sub(1, 30):lower()

					if lower4:find("<!doctype") or lower4:find("<html") or lower4:find("<head") then
						return false
					end

					return true
				end
			end
		end

		local function loadDbdSoundCache()
			local dbdSoundWriteFile = writefile
			local dbdSoundAssetConverter = getDbdCustomAsset()

			if not (dbdSoundWriteFile and readfile and isfile and dbdSoundAssetConverter) then
				return false
			else
				local count5 = 0

				for key2, value29 in pairs({
					Warning = "dbd_skillcheck_sound.wav",
					Great = "dbd_skillcheck_great.ogg",
					Confirm = "dbd_skillcheck_confirm.ogg",
					HookPoint = "dbd_hook_point.ogg",
					HookHit = "dbd_hook_hit.ogg",
					PalletDrop = "dbd_pallet_drop.ogg",
					ExitReady = "dbd_exit_ready.ogg",
					GenExplode = "dbd_gen_explode.ogg",
					GateOpen = "dbd_gate_open.ogg",
					GenDone = "dbd_gen_done.ogg",
				}) do
					if isDbdSoundCacheValid(value29) then
						local dbdLoadSoundOk, dbdLoadedSoundAsset = pcall(dbdSoundAssetConverter, value29)

						if dbdLoadSoundOk and dbdLoadedSoundAsset and type(dbdLoadedSoundAsset) == "string" and #dbdLoadedSoundAsset > 0 then
							dbdSoundAssets[key2] = dbdLoadedSoundAsset
							count5 = count5 + 1
						end
					end
				end

				return count5 > 0
			end
		end

		function _G.VD_DBD.isCached()
			local dbdHasWarningSound = dbdSoundAssets.Warning ~= nil
			local dbdSoundCacheState = dbdHasWarningSound

			if dbdHasWarningSound then
				local dbdHasGreatSound = dbdSoundAssets.Great ~= nil

				local dbdSoundRemainingCacheState = dbdHasGreatSound
					and dbdSoundAssets.Confirm ~= nil
					and dbdSoundAssets.HookPoint ~= nil
					and dbdSoundAssets.HookHit ~= nil
					and dbdSoundAssets.PalletDrop ~= nil
					and dbdSoundAssets.ExitReady ~= nil
					and dbdSoundAssets.GenExplode ~= nil
					and dbdSoundAssets.GateOpen ~= nil
					and dbdSoundAssets.GenDone ~= nil

				dbdSoundCacheState = dbdSoundRemainingCacheState
			end

			return dbdSoundCacheState
		end

		local function downloadDbdSounds(dbdSoundProgressCallback)
			if not isDbdActive() or dbdSoundsDownloading then
				return
			end

			dbdSoundsDownloading = true

			task.spawn(function()
				local dbdSoundDownloadItems = {
					{
						key = "Warning",
						file = "dbd_skillcheck_sound.wav",
						url = "https://files.catbox.moe/ld6n7a.wav",
						fallbackUrl = "http://78.154.103.2:9156/sounds/dbd_warning.wav",
						name = "Warning Alert",
					},
					{
						key = "Great",
						file = "dbd_skillcheck_great.ogg",
						url = "https://files.catbox.moe/2nfj25.ogg",
						fallbackUrl = "http://78.154.103.2:9156/sounds/dbd_great.ogg",
						name = "Great Hit",
					},
					{
						key = "Confirm",
						file = "dbd_skillcheck_confirm.ogg",
						url = "https://files.catbox.moe/d726qn.ogg",
						fallbackUrl = "http://78.154.103.2:9156/sounds/dbd_confirm.ogg",
						name = "Good Hit (Confirm)",
					},
					{
						key = "HookPoint",
						file = "dbd_hook_point.ogg",
						url = "https://files.catbox.moe/bcsue6.ogg",
						fallbackUrl = "http://78.154.103.2:9156/sounds/Hooked.ogg",
						name = "Hook Point Sound",
					},
					{
						key = "HookHit",
						file = "dbd_hook_hit.ogg",
						url = "https://files.catbox.moe/bcsue6.ogg",
						fallbackUrl = "http://78.154.103.2:9156/sounds/dbd_hook.ogg",
						name = "Hook Hit Sound",
					},
					{
						key = "PalletDrop",
						file = "dbd_pallet_drop.ogg",
						url = "https://files.catbox.moe/1jx6jp.ogg",
						fallbackUrl = "https://files.catbox.moe/1jx6jp.ogg",
						name = "Pallet Drop",
					},
					{
						key = "ExitReady",
						file = "dbd_exit_ready.ogg",
						url = "https://files.catbox.moe/ubu3bg.ogg",
						fallbackUrl = "https://files.catbox.moe/ubu3bg.ogg",
						name = "Exit Ready (Endgame)",
					},
					{
						key = "GenExplode",
						file = "dbd_gen_explode.ogg",
						url = "https://files.catbox.moe/zh8nxt.ogg",
						fallbackUrl = "https://files.catbox.moe/zh8nxt.ogg",
						name = "Generator Explode",
					},
					{
						key = "GateOpen",
						file = "dbd_gate_open.ogg",
						url = "https://files.catbox.moe/8blge2.ogg",
						fallbackUrl = "https://files.catbox.moe/8blge2.ogg",
						name = "Exit Gate Opening",
					},
					{
						key = "GenDone",
						file = "dbd_gen_done.ogg",
						url = "https://files.catbox.moe/tgy10c.ogg",
						fallbackUrl = "https://files.catbox.moe/tgy10c.ogg",
						name = "Generator Completed",
					},
				}

				local dbdSoundDownloadCount = #dbdSoundDownloadItems
				local dbdDownloadAssetConverter = getDbdCustomAsset()
				local dbdPreloadSounds = {}

				for index29, value30 in ipairs(dbdSoundDownloadItems) do
					if not isDbdActive() then
						for _, sound in ipairs(dbdPreloadSounds) do pcall(function() sound:Destroy() end) end
						dbdSoundsDownloading = false
						return
					end
					local dbdCurrentSoundProgress = (index29 - 1) / dbdSoundDownloadCount
					local dbdSoundProgressMessage = "Downloading "
						.. value30.name
						.. " ("
						.. index29
						.. "/"
						.. dbdSoundDownloadCount
						.. ")..."

					if dbdSoundProgressCallback then
						pcall(dbdSoundProgressCallback, dbdCurrentSoundProgress, dbdSoundProgressMessage)
					end

					notifyDbdSoundListeners(dbdCurrentSoundProgress, dbdSoundProgressMessage)
					local dbdSoundDownloadBody = downloadDbdSoundResource(value30.url)

					if not dbdSoundDownloadBody or #dbdSoundDownloadBody < 500 then
						dbdSoundDownloadBody = downloadDbdSoundResource(value30.fallbackUrl)
					end

					if not isDbdActive() then
						for _, sound in ipairs(dbdPreloadSounds) do pcall(function() sound:Destroy() end) end
						dbdSoundsDownloading = false
						return
					end
					if dbdSoundDownloadBody and #dbdSoundDownloadBody > 500 and writefile then
						pcall(writefile, value30.file, dbdSoundDownloadBody)
					end

					if isDbdSoundCacheValid(value30.file) and dbdDownloadAssetConverter then
						local dbdConvertSoundOk, dbdConvertedSound = pcall(dbdDownloadAssetConverter, value30.file)

						if dbdConvertSoundOk and dbdConvertedSound then
							dbdSoundAssets[value30.key] = dbdConvertedSound

							local sound = Instance.new("Sound")
							sound.SoundId = dbdConvertedSound
							sound.Volume = 0

							table.insert(dbdPreloadSounds, sound)
						end
					end

					task.wait(0.08)
				end

				if #dbdPreloadSounds > 0 then
					if dbdSoundProgressCallback then
						pcall(dbdSoundProgressCallback, 0.92, "Pre-caching audio into memory...")
					end

					notifyDbdSoundListeners(0.92, "Pre-caching audio into memory...")

					pcall(function()
						local contentProvider = game:GetService("ContentProvider")
						contentProvider:PreloadAsync(dbdPreloadSounds)

						for index30, value31 in ipairs(dbdPreloadSounds) do
							value31:Destroy()
						end
					end)
				end

				task.wait(0.1)
				dbdSoundsDownloading = false
				local dbdDownloadedWarning = dbdSoundAssets.Warning ~= nil
				local dbdAllSoundsReady = dbdDownloadedWarning

				if dbdDownloadedWarning then
					local dbdDownloadedGreat = dbdSoundAssets.Great ~= nil

					local dbdAllRemainingSoundsReady = dbdDownloadedGreat
						and dbdSoundAssets.Confirm ~= nil
						and dbdSoundAssets.HookPoint ~= nil
						and dbdSoundAssets.HookHit ~= nil
						and dbdSoundAssets.PalletDrop ~= nil
						and dbdSoundAssets.ExitReady ~= nil
						and dbdSoundAssets.GenExplode ~= nil
						and dbdSoundAssets.GateOpen ~= nil
						and dbdSoundAssets.GenDone ~= nil

					dbdAllSoundsReady = dbdAllRemainingSoundsReady
				end

				local dbdFinalSoundStatus = dbdAllSoundsReady and "Ready (10/10 Sounds Cached)" or "Download Complete"

				if dbdSoundProgressCallback then
					pcall(dbdSoundProgressCallback, 1, dbdFinalSoundStatus)
				end

				notifyDbdSoundListeners(1, dbdFinalSoundStatus)

				if showNotification then
					if dbdAllSoundsReady then
						showNotification("DBD Sounds", "All 10 DBD original audio files cached successfully!", "success")
					else
						showNotification("DBD Sounds", "Sounds downloaded! Ready to use.", "info")
					end
				end
			end)
		end

		_G.VD_DBD.downloadAll = downloadDbdSounds

		local function shouldSuppressDbdSounds()
			if isSpectating and isSpectating() then
				return true
			elseif localPlayer5 then
				if localPlayer5.Team then
					local lower5 = tostring(localPlayer5.Team.Name):lower()

					if lower5:find("spectat") or lower5 == "lobby" then
						return true
					end
				end

				if localPlayer5:GetAttribute("IsSpectating") == true or localPlayer5:GetAttribute("Spectating") == true then
					return true
				end

				return false
			else
				return false
			end
		end

		local dbdSoundLastPlayed = {}

		local function playDbdSound(dbdSoundKind)
			local dbdSoundPlaybackDisabled = (
				((not settings2.DBDSounds) or not settings2.DBDSounds.Enabled) or shouldSuppressDbdSounds()
			)

			local sound2

			if dbdSoundPlaybackDisabled then
				return
			else
				local dbdCurrentSoundTime = os.clock()

				if dbdSoundLastPlayed[dbdSoundKind] and dbdCurrentSoundTime - dbdSoundLastPlayed[dbdSoundKind] < 0.08 then
					return
				else
					dbdSoundLastPlayed[dbdSoundKind] = dbdCurrentSoundTime
					local dbdCachedSoundAsset = dbdSoundAssets[dbdSoundKind]

					if not dbdCachedSoundAsset then
						loadDbdSoundCache()
						dbdCachedSoundAsset = dbdSoundAssets[dbdSoundKind]
					end

					if not dbdCachedSoundAsset then
						if not dbdSoundsDownloading then
							task.spawn(downloadDbdSounds)
						end

						return
					else
						local currentCamera3 = workspace.CurrentCamera
							or localPlayer5:FindFirstChildOfClass("PlayerGui")
							or game:GetService("SoundService")

						sound2 = Instance.new("Sound")
						sound2.Name = "DBD_FX_" .. dbdSoundKind
						sound2.SoundId = dbdCachedSoundAsset
						sound2.Volume = settings2.DBDSounds and settings2.DBDSounds.Volume or 1
						sound2.PlayOnRemove = false
						sound2.Parent = currentCamera3

						pcall(function()
							local soundService = game:GetService("SoundService")
							soundService:PlayLocalSound(sound2)
						end)

						pcall(function()
							sound2:Play()
						end)

						task.delay(4, function()
							pcall(function()
								sound2:Stop()
								sound2:Destroy()
							end)
						end)

						return
					end
				end
			end
		end

		_G.VD_DBD.playEffect = playDbdSound

		local function classifyDbdSound(dbdOriginalSound)
			local dbdSoundMissing = not dbdOriginalSound
			local dbdSoundNameIsDone, complete, parent2

			if dbdSoundMissing or not dbdOriginalSound:IsA("Sound") then
				return nil
			else
				local lower6 = dbdOriginalSound.Name:lower()
				local lower7 = tostring(dbdOriginalSound.SoundId or ""):lower()

				if lower7:find("84082802102438") then
					return "Warning"
				elseif lower7:find("87743901501619") then
					return "Great"
				elseif lower7:find("109250612395512") then
					return "Confirm"
				elseif lower7:find("108630192794160") then
					return "HookPoint"
				elseif lower7:find("78575114991208") then
					return "HookHit"
				elseif lower7:find("102000788089804") then
					return "PalletDrop"
				elseif lower7:find("90802467356489") then
					return "ExitReady"
				elseif lower7:find("97406178741226") then
					return "GenExplode"
				elseif lower7:find("123265859114838") then
					return "GateOpen"
				elseif lower7:find("124429695332529") then
					return "GenDone"
				else
					local parent3 = dbdOriginalSound.Parent
					local dbdSoundNearPallet = false
					local dbdSoundNearSkillCheck = false
					local dbdSoundNearHook = false
					local dbdSoundNearGenerator = false
					local dbdSoundNearGate = false
					local count6 = 0

					while true do
						count6 = 1 + count6

						if not (count6 <= 6) then
							break
						end

						if not parent3 then
							break
						else
							local lower8 = parent3.Name:lower()

							if lower8:find("pallet") then
								dbdSoundNearPallet = true
							end

							if lower8:find("skillcheck") or lower8:find("prompt") or lower8:find("check") then
								dbdSoundNearSkillCheck = true
							end

							if lower8:find("hook") then
								dbdSoundNearHook = true
							end

							if lower8:find("generator") or lower8:find("gen") then
								dbdSoundNearGenerator = true
							end

							if lower8:find("exitlever") or lower8:find("gate") or lower8:find("exitgate") then
								dbdSoundNearGate = true
							end

							parent3 = parent3.Parent
						end
					end

					if dbdSoundNearGate then
						return "GateOpen"
					elseif dbdSoundNearPallet then
						return "PalletDrop"
					elseif dbdSoundNearHook then
						if lower6:find("hit") then
							return "HookHit"
						end

						return "HookPoint"
					else
						if dbdSoundNearGenerator then
							if lower6 == "done" or lower6:find("complete") or lower6:find("finish") or lower6:find("fixed") then
								return "GenDone"
							end

							if
								lower6 == "burn"
								or lower6:find("explode")
								or lower6:find("explosion")
								or lower6:find("spark")
								or lower6:find("boom")
								or lower6:find("fail")
							then
								return "GenExplode"
							end
						end

						if dbdSoundNearSkillCheck then
							if lower6 == "sound" or lower6:find("warn") or lower6:find("alert") then
								return "Warning"
							end

							if lower6 == "great" or lower6:find("great") or lower6:find("perfect") then
								return "Great"
							end

							if
								lower6 == "confirm"
								or lower6:find("confirm")
								or lower6:find("good")
								or lower6:find("hit")
								or lower6:find("success")
							then
								return "Confirm"
							end

							dbdSoundNameIsDone = lower6 == "done"

							complete = dbdSoundNameIsDone
							complete = dbdSoundNameIsDone or lower6:find("complete")

							parent2 = complete
							parent2 = complete and dbdOriginalSound.Parent and dbdOriginalSound.Parent.Name:lower() == "hitbox"

							if parent2 then
								return "GenDone"
							end

							if lower6 == "burn" and dbdOriginalSound.Parent and dbdOriginalSound.Parent.Name:lower() == "hitbox" then
								return "GenExplode"
							end

							if lower6:find("warning") or lower6:find("alert") or lower6:find("skillcheck_sound") then
								return "Warning"
							end

							if lower6 == "great" or lower6:find("great") then
								return "Great"
							end

							if lower6 == "confirm" or lower6:find("confirm") or lower6:find("good") then
								return "Confirm"
							end

							return nil
						end

						dbdSoundNameIsDone = lower6 == "done"

						complete = dbdSoundNameIsDone
						complete = dbdSoundNameIsDone or lower6:find("complete")

						parent2 = complete
						parent2 = complete and dbdOriginalSound.Parent and dbdOriginalSound.Parent.Name:lower() == "hitbox"

						if parent2 then
							return "GenDone"
						end

						if lower6 == "burn" and dbdOriginalSound.Parent and dbdOriginalSound.Parent.Name:lower() == "hitbox" then
							return "GenExplode"
						end

						if lower6:find("warning") or lower6:find("alert") or lower6:find("skillcheck_sound") then
							return "Warning"
						end

						if lower6 == "great" or lower6:find("great") then
							return "Great"
						end

						if lower6 == "confirm" or lower6:find("confirm") or lower6:find("good") then
							return "Confirm"
						end

						return nil
					end
				end
			end
		end

		local dbdSoundKinds = setmetatable({}, { __mode = "k" })
		local dbdOriginalVolumes = setmetatable({}, { __mode = "k" })

		local function hookDbdSound(dbdSoundToHook)
			if not isDbdActive() or not dbdSoundToHook or not dbdSoundToHook:IsA("Sound") or dbdOriginalVolumes[dbdSoundToHook] then
				return
			end

			local resolveDbdSoundKind

			function resolveDbdSoundKind()
				local dbdDetectedSoundKind = classifyDbdSound(dbdSoundToHook)

				if dbdDetectedSoundKind then
					dbdSoundKinds[dbdSoundToHook] = dbdDetectedSoundKind
					return dbdDetectedSoundKind
				end

				return dbdSoundKinds[dbdSoundToHook]
			end

			local onDbdSoundPlaying

			if not resolveDbdSoundKind() then
				return
			else
				dbdOriginalVolumes[dbdSoundToHook] = dbdSoundToHook.Volume > 0 and dbdSoundToHook.Volume or 1

				if dbdSoundToHook:GetAttribute("DBD_OrigVol") == nil and dbdSoundToHook.Volume > 0 then
					dbdSoundToHook:SetAttribute("DBD_OrigVol", dbdSoundToHook.Volume)
				end

				local function updateDbdOriginalVolume()
					if (settings2.DBDSounds and settings2.DBDSounds.Enabled) and not shouldSuppressDbdSounds() then
						if dbdSoundToHook.Volume > 0 then
							if dbdSoundToHook:GetAttribute("DBD_OrigVol") == nil then
								dbdSoundToHook:SetAttribute("DBD_OrigVol", dbdSoundToHook.Volume)
							end

							dbdSoundToHook.Volume = 0
						end
					else
						local dbdOrigVol = dbdSoundToHook:GetAttribute("DBD_OrigVol") or dbdOriginalVolumes[dbdSoundToHook]

						if dbdOrigVol and dbdSoundToHook.Volume == 0 then
							dbdSoundToHook.Volume = dbdOrigVol
						end
					end
				end

				updateDbdOriginalVolume()

				registerConnection(dbdSoundToHook:GetPropertyChangedSignal("Volume"):Connect(function()
					if isDbdActive() and (settings2.DBDSounds and settings2.DBDSounds.Enabled) and not shouldSuppressDbdSounds() then
						if dbdSoundToHook.Volume > 0 then
							dbdSoundToHook.Volume = 0
						end
					end
				end))

				function onDbdSoundPlaying()
					if not isDbdActive() or not (settings2.DBDSounds and settings2.DBDSounds.Enabled) or shouldSuppressDbdSounds() then
						return
					else
						local dbdPlayingSoundKind = resolveDbdSoundKind()

						if not dbdPlayingSoundKind then
							return
						end

						if dbdSoundToHook.Volume > 0 then
							dbdSoundToHook.Volume = 0
						end

						playDbdSound(dbdPlayingSoundKind)
						return
					end
				end

				registerConnection(dbdSoundToHook.Played:Connect(onDbdSoundPlaying))

				registerConnection(dbdSoundToHook:GetPropertyChangedSignal("Playing"):Connect(function()
					if dbdSoundToHook.Playing then
						onDbdSoundPlaying()
					end
				end))

				return
			end
		end

		_G.VD_DBD.hookSound = hookDbdSound

		function _G.VD_DBD.restoreSounds()
			for key3, value32 in pairs(dbdOriginalVolumes) do
				local dbdOriginalSoundObject = key3
				local dbdRememberedVolume = value32

				if dbdOriginalSoundObject and dbdOriginalSoundObject.Parent then
					pcall(function()
						local dbdOrigVol2 = dbdOriginalSoundObject:GetAttribute("DBD_OrigVol") or dbdRememberedVolume

						if dbdOrigVol2 and dbdOrigVol2 > 0 then
							dbdOriginalSoundObject.Volume = dbdOrigVol2
						end

						dbdOriginalSoundObject:SetAttribute("DBD_OrigVol", nil)
					end)
				end
			end
		end

		local function applyDbdSounds(dbdSkillCheckContainer)
			if not dbdSkillCheckContainer then
				return
			end

			if not (settings2.DBDSounds and settings2.DBDSounds.Enabled) then
				return
			else
				local dbdWarningMissing = not dbdSoundAssets.Warning
				local dbdSoundAssetsIncomplete = dbdWarningMissing

				if not dbdWarningMissing then
					local dbdGreatMissing = not dbdSoundAssets.Great

					local dbdOtherSoundsMissing = dbdGreatMissing
						or not dbdSoundAssets.Confirm
						or not dbdSoundAssets.HookPoint
						or not dbdSoundAssets.HookHit
						or not dbdSoundAssets.PalletDrop
						or not dbdSoundAssets.ExitReady
						or not dbdSoundAssets.GenExplode
						or not dbdSoundAssets.GateOpen
						or not dbdSoundAssets.GenDone

					dbdSoundAssetsIncomplete = dbdOtherSoundsMissing
				end

				if dbdSoundAssetsIncomplete then
					loadDbdSoundCache()
				end

				if dbdSkillCheckContainer:IsA("Sound") then
					hookDbdSound(dbdSkillCheckContainer)
				else
					for index31, value33 in ipairs(dbdSkillCheckContainer:GetDescendants()) do
						if value33:IsA("Sound") then
							hookDbdSound(value33)
						end
					end
				end

				return
			end
		end

		_G.VD_DBD.apply = applyDbdSounds

