		local function downloadDbdHudResource(dbdHudUrl)
			local dbdHudRequest = syn and syn.request or http and http.request or http_request or fluxus and fluxus.request or request

			local dbdHudGetResult, dbdHudGetOk, dbdHudGetStatus

			if dbdHudRequest then
				for i = 1, 3 do
					local dbdHudRequestOk, dbdHudResponse = pcall(dbdHudRequest, {
						Url = dbdHudUrl,
						Method = "GET",
						Headers = {
							["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120.0.0.0 Safari/537.36",
							Accept = "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
						},
					})

					if dbdHudRequestOk and type(dbdHudResponse) == "table" then
						local body2 = dbdHudResponse.Body or dbdHudResponse.body or dbdHudResponse.response
						local statusCode2 = dbdHudResponse.StatusCode or dbdHudResponse.status_code or dbdHudResponse.Status or 200

						if body2 and #body2 > 50 and (statusCode2 == 200 or statusCode2 == 0) then
							return body2
						end
					end

					task.wait(0.2)
				end

				dbdHudGetOk, dbdHudGetResult = pcall(function()
					return game:HttpGet(dbdHudUrl)
				end)

				dbdHudGetStatus = dbdHudGetOk
				dbdHudGetStatus = dbdHudGetOk and dbdHudGetResult and #dbdHudGetResult > 50

				if dbdHudGetStatus then
					return dbdHudGetResult
				else
					local dbdHudHttpOk, dbdHudHttpBody = pcall(function()
						return game:HttpGet(dbdHudUrl, true)
					end)

					if dbdHudHttpOk and dbdHudHttpBody and #dbdHudHttpBody > 50 then
						return dbdHudHttpBody
					end

					return nil
				end
			else
				dbdHudGetOk, dbdHudGetResult = pcall(function()
					return game:HttpGet(dbdHudUrl)
				end)

				dbdHudGetStatus = dbdHudGetOk
				dbdHudGetStatus = dbdHudGetOk and dbdHudGetResult and #dbdHudGetResult > 50

				if dbdHudGetStatus then
					return dbdHudGetResult
				else
					local dbdHudFallbackOk, dbdHudFallbackBody = pcall(function()
						return game:HttpGet(dbdHudUrl, true)
					end)

					if dbdHudFallbackOk and dbdHudFallbackBody and #dbdHudFallbackBody > 50 then
						return dbdHudFallbackBody
					end

					return nil
				end
			end
		end

		local dbdHudListeners = {}

		local function registerDbdHudListener(dbdHudListener)
			if type(dbdHudListener) == "function" then
				table.insert(dbdHudListeners, dbdHudListener)
