				pcall(value34, dbdHudProgress, dbdHudStatus)
			end
		end

		local function isDbdHudFullyCached()
			return dbdHudAssets.Healthy ~= nil
				and dbdHudAssets.Injured ~= nil
				and dbdHudAssets.Knocked ~= nil
				and dbdHudAssets.Hooked ~= nil
				and dbdHudAssets.Carried ~= nil
				and dbdHudAssets.Chased ~= nil
				and dbdHudAssets.Gen ~= nil
		end

		local function loadDbdHudCache()
			local dbdHudCacheConverter = getDbdHudCustomAsset()

			if not (writefile and readfile and isfile and dbdHudCacheConverter) then
				return
			end

			for key4, value35 in pairs(dbdHudResources) do
				if isfile(value35.file) then
					local dbdHudCacheConvertOk, dbdHudCachedAsset = pcall(dbdHudCacheConverter, value35.file)

					if dbdHudCacheConvertOk and dbdHudCachedAsset and type(dbdHudCachedAsset) == "string" and #dbdHudCachedAsset > 0 then
						dbdHudAssets[key4] = dbdHudCachedAsset
					end
				end
			end
		end

		local function downloadDbdHud(dbdHudProgressCallback)
			if type(dbdHudProgressCallback) == "function" then
				registerDbdHudListener(dbdHudProgressCallback)
			end

			if not isDbdActive() or dbdHudDownloading then
				return
			end

			dbdHudDownloading = true

			task.spawn(function()
				local dbdHudDownloadItems = {
					{ key = "Healthy", item = dbdHudResources.Healthy },
					{ key = "Injured", item = dbdHudResources.Injured },
					{ key = "Knocked", item = dbdHudResources.Knocked },
					{ key = "Hooked", item = dbdHudResources.Hooked },
					{ key = "Carried", item = dbdHudResources.Carried },
					{ key = "Chased", item = dbdHudResources.Chased },
					{ key = "Gen", item = dbdHudResources.Gen },
				}

				local dbdHudDownloadCount = #dbdHudDownloadItems
				local dbdHudDownloadConverter = getDbdHudCustomAsset()
				notifyDbdHudListeners(0, "Starting DBD HUD download...")

				for index33, value36 in ipairs(dbdHudDownloadItems) do
					if not isDbdActive() then
						dbdHudDownloading = false
						return
					end
					local key5 = value36.key
					local item = value36.item

					if not dbdHudAssets[key5] then
						notifyDbdHudListeners(
							(index33 - 1) / dbdHudDownloadCount,
							string.format("Downloading %s icon (%d/%d)...", key5, index33, dbdHudDownloadCount)
						)

						if not (isfile and isfile(item.file)) then
							local dbdHudDownloadBody = downloadDbdHudResource(item.url)

							if not isDbdActive() then
								dbdHudDownloading = false
								return
							end
							if dbdHudDownloadBody and #dbdHudDownloadBody > 50 and writefile then
								pcall(writefile, item.file, dbdHudDownloadBody)
							end

							task.wait(0.15)
						end

						if isfile and isfile(item.file) and dbdHudDownloadConverter then
							local dbdHudConvertOk, dbdHudConvertedAsset = pcall(dbdHudDownloadConverter, item.file)

							if
								dbdHudConvertOk
								and dbdHudConvertedAsset
								and type(dbdHudConvertedAsset) == "string"
								and #dbdHudConvertedAsset > 0
							then
								dbdHudAssets[key5] = dbdHudConvertedAsset
							end
						end
					end

					notifyDbdHudListeners(
						index33 / dbdHudDownloadCount,
						string.format("Cached %s icon (%d/%d)", key5, index33, dbdHudDownloadCount)
					)
					task.wait(0.05)
				end

				dbdHudDownloading = false

				if isDbdHudFullyCached() then
					notifyDbdHudListeners(1, "Status: Ready (7/7 Cached)")

					if not isAutoStartup and showNotification then
						showNotification("DBD HUD", "All 7 DBD HUD icons downloaded & cached!", "success")
					end
				else
					notifyDbdHudListeners(1, "Status: Partially Cached")

					if not isAutoStartup and showNotification then
						showNotification(" DBD HUD", "Some HUD icons could not be downloaded.", "warning")
					end
				end
			end)
		end

