		local function getDbdPlayerStatus(dbdHudPlayer)
			if not dbdHudPlayer then
				return "Healthy"
			else
				local dbdHudPlayerCarried = dbdHudPlayer:GetAttribute("IsCarried") == true
				local character16 = dbdHudPlayer.Character

				if
					dbdHudPlayerCarried
					or character16 and character16:GetAttribute("IsCarried") == true
					or readModelValue and character16 and readModelValue(character16, "IsCarried") == true
				then
					return "Carried"
				end

				if
					dbdHudPlayer:GetAttribute("IsHooked") == true
					or character16 and character16:GetAttribute("IsHooked") == true
					or readModelValue and character16 and readModelValue(character16, "IsHooked") == true
				then
					return "Hooked"
				else
					local dbdHudPlayerKnocked = dbdHudPlayer:GetAttribute("Knocked") == true
						or dbdHudPlayer:GetAttribute("IsKnocked") == true
						or character16 and (character16:GetAttribute("Knocked") == true or character16:GetAttribute("IsKnocked") == true)
						or readModelValue
							and character16
							and (readModelValue(character16, "Knocked") == true or readModelValue(character16, "IsKnocked") == true)

					if character16 then
						local humanoid8 = character16:FindFirstChildOfClass("Humanoid")

						if humanoid8 and humanoid8.Health <= 0 then
							dbdHudPlayerKnocked = true
						end
					end

					if dbdHudPlayerKnocked then
						return "Knocked"
					end

					if
						dbdHudPlayer:GetAttribute("IsChased") == true
						or character16 and character16:GetAttribute("IsChased") == true
						or readModelValue and character16 and readModelValue(character16, "IsChased") == true
					then
						return "Chased"
					else
						local dbdHudPlayerInjured = dbdHudPlayer:GetAttribute("Injured") == true
							or dbdHudPlayer:GetAttribute("IsInjured") == true
							or character16 and (character16:GetAttribute("Injured") == true or character16:GetAttribute("IsInjured") == true)
							or readModelValue
								and character16
								and (readModelValue(character16, "Injured") == true or readModelValue(character16, "IsInjured") == true)

						if not dbdHudPlayerInjured and character16 then
							local humanoid9 = character16:FindFirstChildOfClass("Humanoid")

							if humanoid9 and humanoid9.MaxHealth > 0 and humanoid9.Health < humanoid9.MaxHealth then
								dbdHudPlayerInjured = true
							end

							if not dbdHudPlayerInjured and getPlayerHealthPercent then
								local dbdHealthCurrent, dbdHealthMaximum = getPlayerHealthPercent(dbdHudPlayer)

								if dbdHealthCurrent and dbdHealthMaximum and dbdHealthCurrent < dbdHealthMaximum then
									dbdHudPlayerInjured = true
								end
							end
						end

						if dbdHudPlayerInjured then
							return "Injured"
						end

						return "Healthy"
					end
				end
			end
		end

