local function vdQueueParticleRateScan(enabled, generation)
	task.spawn(function()
		local ok, descendants = pcall(function()
			return workspace:GetDescendants()
		end)
		if not ok or type(descendants) ~= "table" then
			return
		end
		local batchSize = vdIsMobile and 80 or 160
		local deadline = os.clock() + 0.002
		local function processDescendant(descendant)
			if descendant.Parent and descendant:IsDescendantOf(workspace) and (descendant:IsA("ParticleEmitter") or descendant:IsA("Smoke") or descendant:IsA("Fire") or descendant:IsA("Sparkles")) then
				if enabled then
					if descendant:GetAttribute("_origRate") == nil then
						descendant:SetAttribute("_origRate", descendant.Rate or 1)
					end
					descendant.Rate = 0
				elseif descendant:GetAttribute("_origRate") ~= nil then
					descendant.Rate = descendant:GetAttribute("_origRate")
					descendant:SetAttribute("_origRate", nil)
				end
			end
		end
		for index, descendant in ipairs(descendants) do
			if generation ~= vdPerformanceGeneration or _G.VD_SessionToken ~= vdPerformanceSession then
				return
			end
			pcall(processDescendant, descendant)
			if index % batchSize == 0 or (index % 16 == 0 and os.clock() >= deadline) then
				task.wait()
				deadline = os.clock() + 0.002
			end
		end
	end)
end
function applyPerformanceMode()
