				Y = {
					WaterWaveSize = workspace.Terrain.WaterWaveSize,
					WaterWaveSpeed = workspace.Terrain.WaterWaveSpeed,
					WaterReflectance = workspace.Terrain.WaterReflectance,
				}
			end
			if workspace.Terrain then
				workspace.Terrain.WaterWaveSize = 0
				workspace.Terrain.WaterWaveSpeed = 0
				workspace.Terrain.WaterReflectance = 0
			end
			vdLightingService3.GlobalShadows = false
			for index, child in ipairs(vdLightingService3:GetChildren()) do
				if
					child:IsA("BlurEffect")
					or child:IsA("SunRaysEffect")
					or child:IsA("BloomEffect")
					or child:IsA("DepthOfFieldEffect")
					or child:IsA("Atmosphere")
				then
					if Z[child] == nil then
						Z[child] = child.Enabled
					end
					pcall(function()
						child.Enabled = false
					end)
				end
			end
			vdQueueParticleRateScan(true, generation)
			pcall(function()
				if settings and (settings()).Rendering then
					(settings()).Rendering.QualityLevel = Enum.QualityLevel.Level01
				end
			end)
		else
			if Y and workspace.Terrain then
				workspace.Terrain.WaterWaveSize = Y.WaterWaveSize or 0.15
				workspace.Terrain.WaterWaveSpeed = Y.WaterWaveSpeed or 10
				workspace.Terrain.WaterReflectance = Y.WaterReflectance or 0.05
			end
			if defaultLightingSettings then
				vdLightingService3.GlobalShadows = defaultLightingSettings.GlobalShadows
			end
			for key, value in pairs(Z) do
				if key and key.Parent then
					pcall(function()
