function toBase36(number)
	number = tonumber(number) or 0
	if number == 0 then
		return "0"
	end
	local f = "0123456789abcdefghijklmnopqrstuvwxyz"
	local g = ""
	while number > 0 do
		local c = number % 36
		g = f:sub(c + 1, c + 1) .. g
		number = math.floor(number / 36)
	end
	return g
end
function fromBase36(text_1)
	if not text_1 or text_1 == "" then
		return "0"
	end
	local d = "0123456789abcdefghijklmnopqrstuvwxyz"
	local f = 0
	for index = 1, #text_1, 1 do
		local b = text_1:sub(index, index)
		local e = d:find(b) or 1
		f = f * 36 + (e - 1)
	end
	return tostring(f)
end
