	end, { "Overlay GUI (uses PlayerGui fallback if missing)" })
end
function getUnavailableFeatures()
	local c, d = {}, {}
	for index, value in ipairs(vdCapabilityOrder) do
		local h = vdCapabilities[value]
		if h and not h.available then
			for index2, value2 in ipairs(h.features) do
				if not d[value2] then
					d[value2] = true
					table.insert(c, value2)
				end
			end
		end
	end
	return c
end
function printStartupCapabilityReport()
	local c, d = 0, 0
	for index, value in ipairs(vdCapabilityOrder) do
		local h = vdCapabilities[value]
		if h then
			c = c + 1
			if h.available then
			else
				d = d + 1
			end
		end
	end
	if d == 0 then
	else
	end
end
