function loadSettings()
	loadConfigs()
	local d = vdProfileStore.profiles[vdProfileStore.activeProfile]
	if d then
		deserializeTable(vdSettings, d)
	else
		vdProfileStore.activeProfile = "Default"
		deserializeTable(vdSettings, vdProfileStore.profiles.Default)
	end
	if vdSettings.FirstRunVersion ~= "vv1.7.0_Premium" then
		vdSettings.FirstRunVersion = "vv1.7.0_Premium"
		saveSettings()
	end
	normalizeSettings()
end
function saveSettings()
	if vdProfileStore.profiles[vdProfileStore.activeProfile] == nil then
		vdProfileStore.profiles[vdProfileStore.activeProfile] = {}
	end
	vdProfileStore.profiles[vdProfileStore.activeProfile] = serializeTable(vdSettings)
	saveConfigs()
end
function loadProfile(profileName)
	local d = vdProfileStore.profiles[profileName]
	if not d then
		return
	end
	vdProfileStore.activeProfile = profileName
	deserializeTable(vdSettings, d)
	if vdSettings.RevolverAutofarm then
		vdSettings.InstantHeal = true
	end
	normalizeSettings()
	saveConfigs()

	if applyPerformanceMode then
		pcall(applyPerformanceMode)
	end
	if applyFPSCap then
		pcall(applyFPSCap)
	end
	if vdRefreshControls then
		pcall(vdRefreshControls)
	end
end
