function getDistance(target_2, targetPart_1)
	local g = cachedLocalRoot
	if not g then
		local vdCharacter2 = localPlayer.Character
		g = vdCharacter2 and vdCharacter2:FindFirstChild("HumanoidRootPart")
		if not g then
			return math.huge
		end
	end
	local h = targetPart_1
	if not h then
		if target_2:IsA("Player") then
			local vdCharacter3 = target_2.Character
			h = vdCharacter3 and vdCharacter3:FindFirstChild("HumanoidRootPart")
		elseif target_2:IsA("Model") then
			h = target_2.PrimaryPart or target_2:FindFirstChildWhichIsA("BasePart")
		elseif target_2:IsA("BasePart") then
			h = target_2
		end
	end
	if h then
		return math.round(((g.Position - h.Position)).Magnitude)
	end
	return math.huge
end
_G.VD_FarmState = _G.VD_FarmState or {}
_G.VD_FarmState.farmTeamStartTime = _G.VD_FarmState.farmTeamStartTime or 0
_G.VD_FarmState.farmLastTeamName = _G.VD_FarmState.farmLastTeamName or ""
_G.VD_FarmState.lastKillerSpawnTime = _G.VD_FarmState.lastKillerSpawnTime or 0
_G.VD_FarmState.lastSurvivorSpawnTime = _G.VD_FarmState.lastSurvivorSpawnTime or 0
function updateStatus(d)
	if _G.VD_UpdateFarmStatus then
		pcall(function()
			_G.VD_UpdateFarmStatus(d)
		end)
	end
end
function updateTelemetryAndAFKStates()
	local vdResolvedName1 = localPlayer.Team and localPlayer.Team.Name or ""
	if vdResolvedName1 ~= _G.VD_FarmState.farmLastTeamName then
		_G.VD_FarmState.farmTeamStartTime = tick()
		_G.VD_FarmState.farmLastTeamName = vdResolvedName1
		_G.VD_FarmState.lastKillerSpawnTime = 0
		_G.VD_FarmState.lastSurvivorSpawnTime = 0
	end
	local vdCharacter4 = localPlayer.Character
	local vdResolvedHumanoidRootPart1 = vdCharacter4 and vdCharacter4:FindFirstChild("HumanoidRootPart")
	if vdResolvedName1 == "Killer" and vdResolvedHumanoidRootPart1 then
		if _G.VD_FarmState.lastKillerSpawnTime == 0 then
			_G.VD_FarmState.lastKillerSpawnTime = tick()
		end
	elseif vdResolvedName1 ~= "Killer" then
		_G.VD_FarmState.lastKillerSpawnTime = 0
	end
	if vdResolvedName1 == "Survivors" and vdResolvedHumanoidRootPart1 then
		if _G.VD_FarmState.lastSurvivorSpawnTime == 0 then
			_G.VD_FarmState.lastSurvivorSpawnTime = tick()
		end
	elseif vdResolvedName1 ~= "Survivors" then
		_G.VD_FarmState.lastSurvivorSpawnTime = 0
	end
	local h = tick() - (_G.VD_FarmState.farmTeamStartTime or 0)
	if vdSettings.AutoFarmAFKTotal then
		if vdResolvedName1 == "Survivors" then
			local d = _G.VD_FarmState.lastSurvivorSpawnTime > 0 and (tick() - _G.VD_FarmState.lastSurvivorSpawnTime) or 0
			if _G.VD_FarmState.lastSurvivorSpawnTime == 0 or d < 15 then
				vdSettings.AutoFarmSurvivor = false
				vdSettings.AutoFarmKiller = false
				if _G.VD_SetFarmToggle then
					pcall(function()
						_G.VD_SetFarmToggle(false)
					end)
				end
				if _G.VD_SetKillerFarmToggle then
					pcall(function()
						_G.VD_SetKillerFarmToggle(false)
					end)
				end
				local vdRoundedUp = math.ceil(15 - d)
				updateStatus(string.format("WAITING (%ds)", vdRoundedUp > 0 and vdRoundedUp or 15))
			else
				local d = vdCharacter4
					and (vdReadModelValue(vdCharacter4, "Knocked") == true or vdCharacter4:GetAttribute("Knocked") == true)
				local g = vdCharacter4
					and (vdReadModelValue(vdCharacter4, "IsHooked") == true or vdCharacter4:GetAttribute("IsHooked") == true)
				if d or g then
					vdSettings.AutoFarmSurvivor = false
					vdSettings.AutoFarmKiller = false
					if _G.VD_SetFarmToggle then
						pcall(function()
							_G.VD_SetFarmToggle(false)
						end)
					end
					if _G.VD_SetKillerFarmToggle then
						pcall(function()
							_G.VD_SetKillerFarmToggle(false)
						end)
					end
					updateStatus("PAUSED (Knocked/Hooked)")
				else
					vdSettings.AutoFarmSurvivor = true
					vdSettings.AutoFarmKiller = false
					if _G.VD_FarmState.lastRoundScanned ~= _G.VD_FarmState.lastSurvivorSpawnTime then
						_G.VD_FarmState.lastRoundScanned = _G.VD_FarmState.lastSurvivorSpawnTime
						pcall(scanMapObjects)
						pcall(scanRemotes)
					end
					if _G.VD_SetFarmToggle then
						pcall(function()
							_G.VD_SetFarmToggle(true)
						end)
					end
					if _G.VD_SetKillerFarmToggle then
						pcall(function()
							_G.VD_SetKillerFarmToggle(false)
						end)
					end
					if vdSettings.AutoPumpkin then
						local c = _G.VD_CurrentFarmState
						if c and (c ~= "Idle" and (c ~= "IDLE" and c ~= "OFF")) then
							updateStatus(c)
						else
							updateStatus("RUNNING (Auto Pumpkin)")
