local function vdUpdateGeneratorAnalytics()
	local vdTime = tick()
	local f = vdSettings.MasterESP
		and (vdSettings.GeneratorESP and (vdSettings.GeneratorESP.Enabled and vdSettings.GeneratorESP.AlertThresholdEnabled))
	local g = (vdSettings.GeneratorESP and vdSettings.GeneratorESP.AlertThreshold) or 90
	for index, value in ipairs(cachedGenerators or {}) do
		if not value or not value.Parent then
			continue
		end
		if isGeneratorCompleted(value) then
			vdGeneratorAnalytics[value] = nil
			continue
		end
		local generatorProgress = getGeneratorProgress(value)
		local k = vdGeneratorAnalytics[value]
		if not k then
			vdGeneratorAnalytics[value] = {
				lastProgress = generatorProgress,
				lastTime = vdTime,
				history = {},
				smoothedSpeed = 0,
				smoothedETA = nil,
				etaSeconds = nil,
				etaFormatted = "",
				alertTriggered = (generatorProgress >= g),
			}
			continue
		end
		local l = vdTime - k.lastTime
		if l >= 0.75 then
			local h = generatorProgress - k.lastProgress
			local isGeneratorRegressing_1 = isGeneratorRegressing(value)
			local n = 0
			if h ~= 0 then
				n = h / l
			elseif isGeneratorRegressing_1 then
				if k.smoothedSpeed and k.smoothedSpeed < 0 then
					n = k.smoothedSpeed
				else
					n = -0.5
				end
			else
				n = 0
			end
			table.insert(k.history, n)
			if #k.history > 5 then
				table.remove(k.history, 1)
			end
			local o = 0
			for index2, value2 in ipairs(k.history) do
				o = o + value2
			end
			local p = o / #k.history
			local q = k.smoothedSpeed or 0
			local r = q + (p - q) * 0.25
			if math.abs(r) < 0.05 then
				r = 0
			end
			local s = nil
			local t = ""
			if r > 0.1 then
				local d = 100 - generatorProgress
				local vdMaximum = math.max(0, d / r)
				local g = k.smoothedETA or vdMaximum
				local h = g + (vdMaximum - g) * 0.2
				k.smoothedETA = h
				s = h
				if s < 60 then
					t = string.format("%ds", math.ceil(s))
				else
					local vdRoundedDown = math.floor(s / 60)
					local vdRoundedUp = math.ceil(s % 60)
					t = string.format("%dm %02ds", vdRoundedDown, vdRoundedUp)
				end
			else
				k.smoothedETA = nil
			end
			k.smoothedSpeed = r
			k.etaSeconds = s
			k.etaFormatted = t
			k.lastProgress = generatorProgress
			k.lastTime = vdTime
			if f then
				if generatorProgress >= g then
					if not k.alertTriggered then
						k.alertTriggered = true
						local d = (k.etaFormatted and k.etaFormatted ~= "") and ("ETA: " .. k.etaFormatted) or "Nearly Complete!"
						showNotification(
							"Generator Alert",
							string.format("Generator reached %d%% progress! (%s)", math.floor(generatorProgress), d),
							"warning"
						)
					end
				else
					if generatorProgress < (g - 5) then
						k.alertTriggered = false
					end
				end
			end
		end
	end
end
