		Kb[f] = true
		if _G.VD_LoggedAnimations[f] then
			_G.VD_LoggedAnimations[f].blacklisted = true
		end
		print("[VD PARRY] Added animation ID to Blacklist: " .. f)
		warn("[VD PARRY] Blacklisted: " .. f)
		pcall(function()
			if rconsoleprint then
				rconsoleprint("@@RED@@[VD BLACKLIST] Added: " .. (f .. "\n"))
			end
		end)
		return true
	end
	return false
end
_G.VD_UnblacklistAnimation = function(d)
