local Lb = {}
function updateSCPCache()
	local c = {}
	local d = {}
	local function f(f)
		if f and not d[f] then
			d[f] = true
			table.insert(c, f)
		end
	end
	local vdMap4 = workspace:FindFirstChild("Map")
	if vdMap4 then
		for index, value in ipairs({ "1", "2" }) do
			local foundChild_5 = vdMap4:FindFirstChild(value)
			if foundChild_5 then
				for index2, child in ipairs(foundChild_5:GetChildren()) do
					if child:IsA("Model") then
						f(child)
					end
				end
			end
		end
		local function c(c)
			return string.match(c:lower(), "^scp%d*$") ~= nil
		end
		for index, child in ipairs(vdMap4:GetChildren()) do
			if child.Name ~= "1" and child.Name ~= "2" then
				if child:IsA("Model") and c(child.Name) then
					f(child)
				elseif child:IsA("Folder") or child:IsA("Model") then
					for index2, child2 in ipairs(child:GetChildren()) do
						if child2:IsA("Model") and c(child2.Name) then
							f(child2)
						end
					end
				end
			end
		end
		for index, child in ipairs(vdMap4:GetChildren()) do
			if child:IsA("Model") and child ~= localPlayer.Character then
				local vdResolvedAttributeCured1 = child:GetAttribute("Cured")
				if tonumber(vdResolvedAttributeCured1) == 3 then
					f(child)
				end
			end
		end
	end
	Lb = c
end
local Mb = nil
local Nb = "Unknown Map"
function getMapName()
	local callSucceeded_14, callResult_14 = pcall(function()
		return (game:GetService("Players")).LocalPlayer.PlayerGui.Darkness.Frame.MapInfo.MapTitle.Text
	end)
	if callSucceeded_14 and (callResult_14 and callResult_14 ~= "") then
		if callResult_14:upper() == "NOSTROMO" then
			return "Loading..."
		end
		return callResult_14
	end
	local vdMap5 = workspace:FindFirstChild("Map")
	if not vdMap5 then
		Mb = nil
		Nb = "Unknown Map"
		return Nb
	end
	local h = vdMap5:FindFirstChildOfClass("Model") or vdMap5:FindFirstChildOfClass("Folder") or vdMap5
	if h == Mb and Nb ~= "Unknown Map" then
		return Nb
	end
	Mb = h
	if vdMap5:FindFirstChild("HooksMeat", true) then
		Nb = "BLOODBATH! Club"
		return Nb
	end
	if vdMap5:FindFirstChild("Rooftop", true) then
		Nb = "Mercy Hospital Rooftop"
		return Nb
	end
	if vdMap5:FindFirstChild("inviswallasylum", true) then
		Nb = "Mount Massive Asylum"
		return Nb
	end
	if vdMap5:FindFirstChild("Tesla", true) then
		Nb = "Site 68"
		return Nb
	end
	if vdMap5:FindFirstChild("Breakwater", true) then
		Nb = "The Bay Harbor"
		return Nb
	end
	if vdMap5:FindFirstChild("RockVar0", true) then
		Nb = "Woodview Cabin"
		return Nb
	end
	local vdModel1 = vdMap5:FindFirstChild("Model", true)
	if vdModel1 then
		local vdPosition2 = (vdModel1:GetPivot()).Position
		if ((vdPosition2 - Vector3.new(-811.4, 212.8, -7774.5))).Magnitude < 100 then
			Nb = "Firelink Shrine"
			return Nb
		end
		if ((vdPosition2 - Vector3.new(1114.67, -16.92, -12.99))).Magnitude < 100 then
			Nb = "Valdelobos Village"
			return Nb
		end
	end
	Nb = "Unknown Map"
	return Nb
end
function applyBlockInteractions()
	pcall(function()
		local vdFoundRemotes = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("Window")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("VaultEvent")
		if vdFoundRemotes then
			for index, value in ipairs(cachedVaults) do
				if value and value.Parent then
					for index2, descendant in ipairs(value:GetDescendants()) do
						if descendant.Name == "VaultTrigger" then
							vdFoundRemotes:FireServer(descendant, true)
						end
					end
				end
			end
		end
	end)
	pcall(function()
		local vdFoundRemotes = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("Pallet")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("PalletSlideEvent")
		if vdFoundRemotes then
			for index, value in ipairs(cachedPallets) do
				if value and value.Parent then
					for index2, descendant in ipairs(value:GetDescendants()) do
						if descendant.Name == "PalletPointSlide" or descendant.Name:find("Slide") then
							vdFoundRemotes:FireServer(descendant, true)
						end
					end
				end
			end
		end
	end)
end
function releaseBlockInteractions()
	_G.VD_ReleasingBlockInteractions = true
	pcall(function()
		local vdFoundRemotes = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("Window")
		vdFoundRemotes = vdFoundRemotes and vdFoundRemotes:FindFirstChild("VaultCompleteEvent")
		if vdFoundRemotes then
			local vdMap6 = workspace:FindFirstChild("Map")
			local instance_7 = vdMap6 or workspace
			for index, descendant in ipairs(instance_7:GetDescendants()) do
				if descendant.Name == "VaultTrigger" then
					vdFoundRemotes:FireServer(descendant, false)
				end
			end
		end
	end)
	_G.VD_ReleasingBlockInteractions = false
