					if value.Character then
						playerCharacters[value.Character] = true
					end
				end
				local vdMap7 = workspace:FindFirstChild("Map")
				if not activeLoop or generation ~= vdMapScanGeneration or (isInLobby and isInLobby()) or not vdMap7 then
					return
				end
				local vdResolvedDescendants1 = vdMap7:GetDescendants()
				local batchSize = vdIsMobile and 80 or 160
