local function Ob(c, d)
	local f = c.Tracer
	if not f then
		return
	end
	pcall(function()
		if type(f) == "table" then
			for key, value in pairs(f) do
				if type(value) == "table" or type(value) == "userdata" then
					pcall(function()
						value.Visible = d
					end)
				end
			end
		elseif typeof(f) == "Instance" then
			f.Visible = d
		end
	end)
end
function removePlayerESP(player_1)
