				d.Highlight:Destroy()
			end)
		end
		if d.Billboard then
			pcall(function()
				d.Billboard:Destroy()
			end)
		end
		if d.Tracer then
			pcall(function()
				if type(d.Tracer) == "table" then
					for key, value in pairs(d.Tracer) do
						if type(value) == "table" or type(value) == "userdata" then
							pcall(function()
