		if vdIntact2 then
			if vdIntact2:IsA("BasePart") then
				return vdIntact2
			end
			if vdIntact2:IsA("Model") then
				return vdIntact2.PrimaryPart or vdIntact2:FindFirstChildWhichIsA("BasePart")
			end
		end
		return model_1.PrimaryPart or model_1:FindFirstChildWhichIsA("BasePart")
	end
	if model_1:IsA("BasePart") then
		return model_1
	end
	return nil
end
function getVaultHighlightPart(vault)
