	if not vdBottom1 or not vdBottom1:IsA("BasePart") then
		local modelTargetPart = getModelTargetPart(vault)
		if modelTargetPart and modelTargetPart:IsA("BasePart") then
			return modelTargetPart
		end
		if vault:IsA("BasePart") then
			return vault
		end
		return vault:FindFirstChildWhichIsA("BasePart") or vault
	end
	local f = nil
	local g = math.huge
	for index, descendant in ipairs(vault:GetDescendants()) do
		if descendant:IsA("BasePart") and (descendant ~= vdBottom1 and descendant.Name ~= "HumanoidRootPart") then
			if descendant.Transparency < 1 then
				local vdMagnitude4 = ((descendant.Position - vdBottom1.Position)).Magnitude
				if vdMagnitude4 < g then
					g = vdMagnitude4
					f = descendant
				end
			end
		end
	end
	return f or vdBottom1
end
