						local character = player ~= localPlayer and player.Character
						if character and character:GetAttribute("IsHooked") == true then
							local root = character:FindFirstChild("HumanoidRootPart")
							if root then
								table.insert(hookedRoots, root)
							end
						end
					end
				end
				for _, root in ipairs(hookedRoots) do
					if ((root.Position - c)).Magnitude <= 15 then
						n = Color3.fromRGB(180, 20, 20)
						break
