function manageHighlights()
	local d = {}
	for key, value in pairs(ActiveESP.Players) do
		if value.Highlight and value.LastAuraEnabled then
			table.insert(d, {
				data = value,
				priority = 1,
				dist = getDistance(key, value.Billboard and value.Billboard.Adornee),
			})
		else
			value.TargetHighlightVisible = false
		end
	end
	local f = {
		ActiveESP.SCPs,
		ActiveESP.Generators,
		ActiveESP.Hooks,
		ActiveESP.Pallets,
		ActiveESP.Vaults,
		ActiveESP.BloodEffects,
		ActiveESP.Gates,
		ActiveESP.BearTraps,
		ActiveESP.Pumpkins,
	}
	for index, value in ipairs(f) do
		local h = 4
		if index == 1 then
			h = 2
		elseif index == 2 or index == 7 or index == 8 then
			h = 3
		end
		for key, value2 in pairs(value) do
			if value2.Highlight and value2.LastAuraEnabled then
				table.insert(d, { data = value2, priority = h, dist = getDistance(key, value2.LastBillboardAdornee) })
			else
				value2.TargetHighlightVisible = false
			end
		end
	end
	table.sort(d, function(c, d)
		if c.priority ~= d.priority then
			return c.priority < d.priority
		end
		return c.dist < d.dist
	end)
	local g = 28
	for index, value in ipairs(d) do
		local h = (index <= g)
		value.data.TargetHighlightVisible = h
		if (vdSettings.ESPFadeDuration or 0.2) <= 0.01 then
			if value.data.Highlight:IsA("Highlight") then
				if value.data.Highlight.Enabled ~= h then
					value.data.Highlight.Enabled = h
				end
			elseif value.data.Highlight:IsA("BoxHandleAdornment") then
				if value.data.Highlight.Visible ~= h then
					value.data.Highlight.Visible = h
				end
			end
			if value.data.PuddleHighlight and value.data.PuddleHighlight:IsA("Highlight") then
				if value.data.PuddleHighlight.Enabled ~= h then
					value.data.PuddleHighlight.Enabled = h
				end
			end
		end
	end
end
local fadeMapEspLists = nil
function updateESPFadeTransitions(deltaTime_1)
	if not vdSettings.MasterESP then
		return
	end
	local f = vdSettings.PerformanceMode
	local g = f and 0 or (vdSettings.ESPFadeDuration or 0.2)
	local h = f or (g <= 0.01)
	local i = vdSettings.ESPFillTransparency or 0.6
	local j = vdSettings.ESPOutlineTransparency or 0.1
	local function k(f, k)
		if not f or not f.Highlight then
			return
		end
		local l = 0
		if f.TargetHighlightVisible ~= false and f.LastAuraEnabled then
			l = f.DistanceOpacityFactor or 1
		end
		if f.CurrentAlpha == nil then
			f.CurrentAlpha = l
		elseif h then
			f.CurrentAlpha = l
		else
			local h = deltaTime_1 / g
			if f.CurrentAlpha < l then
				f.CurrentAlpha = math.min(l, f.CurrentAlpha + h)
			elseif f.CurrentAlpha > l then
				f.CurrentAlpha = math.max(l, f.CurrentAlpha - h)
			end
		end
		local m = f.CurrentAlpha
		local n = m > 0.005
		if f.LastFadeAlpha == m and (f.LastFadeFill == i and (f.LastFadeOutline == j and f.LastFadeVis == n)) then
			return
		end
		f.LastFadeAlpha = m
		f.LastFadeFill = i
		f.LastFadeOutline = j
		f.LastFadeVis = n
		if k then
			if f.Highlight:IsA("BoxHandleAdornment") then
				if f.Highlight.Visible ~= n then
					f.Highlight.Visible = n
				end
				if n then
					f.Highlight.Transparency = 1 - ((1 - i) * m)
				end
			end
		else
			if f.Highlight:IsA("Highlight") then
				if f.Highlight.Enabled ~= n then
					f.Highlight.Enabled = n
				end
				if n then
					f.Highlight.FillTransparency = 1 - ((1 - i) * m)
					f.Highlight.OutlineTransparency = 1 - ((1 - j) * m)
				end
			end
			if f.PuddleHighlight and f.PuddleHighlight:IsA("Highlight") then
				if f.PuddleHighlight.Enabled ~= n then
					f.PuddleHighlight.Enabled = n
				end
				if n then
					f.PuddleHighlight.FillTransparency = 1 - ((1 - i) * m)
					f.PuddleHighlight.OutlineTransparency = 1 - ((1 - j) * m)
				end
			end
		end
	end
	for key, value in pairs(ActiveESP.Players) do
		k(value, false)
	end
	if not fadeMapEspLists then
		fadeMapEspLists = {
			ActiveESP.Generators,
			ActiveESP.Hooks,
			ActiveESP.Pallets,
			ActiveESP.BloodEffects,
			ActiveESP.Gates,
			ActiveESP.SCPs,
			ActiveESP.BearTraps,
			ActiveESP.Pumpkins,
		}
	end
	for index, value in ipairs(fadeMapEspLists) do
		for key, value2 in pairs(value) do
			k(value2, false)
		end
	end
	for key, value in pairs(ActiveESP.Vaults) do
		k(value, true)
	end
end
