function showStartupCapabilityReport()
	local unavailableFeatures = getUnavailableFeatures()
	if #unavailableFeatures == 0 then
		showNotification("Compatibility Check", "All features supported on " .. (vdGetExecutorName() .. "."), "success")
		return
	end
	local vdJoinedText = table.concat(unavailableFeatures, ", ")
	if #vdJoinedText > 90 then
		vdJoinedText = vdJoinedText:sub(1, 87) .. "..."
	end
	showNotification("Compatibility Warning", #unavailableFeatures .. (" feature group(s) may not work: " .. vdJoinedText), "warning")
end
