local dc = false
local vdCameraControl = (function()
	local cursorSnapshot = nil
	local thirdPersonSnapshot = nil
	local lobbyCameraDragging = false
	local controller = { window = nil }
	local cursorIcon = "rbxassetid://26140499"

	local function updateContext(snapshot)
		local camera = workspace.CurrentCamera
		snapshot.character = localPlayer.Character
		snapshot.team = localPlayer.Team
		snapshot.camera = camera
		snapshot.cameraType = camera and camera.CameraType or nil
	end

	local function sameContext(snapshot)
		local camera = workspace.CurrentCamera
		return snapshot.character == localPlayer.Character
			and snapshot.team == localPlayer.Team
			and snapshot.camera == camera
			and snapshot.cameraType == (camera and camera.CameraType or nil)
	end

	local cursorGuiService = game:GetService("GuiService")
	local cursorReplicatedStorage = game:GetService("ReplicatedStorage")
	local cursorBindingName = nil

	local function rememberMouse()
		if cursorSnapshot and sameContext(cursorSnapshot) then
			return cursorSnapshot
		end
		local previous = cursorSnapshot
		cursorSnapshot = nil
		local ok, snapshot = pcall(function()
			local state = {
				behavior = UserInputService.MouseBehavior,
				iconEnabled = UserInputService.MouseIconEnabled,
			}
			updateContext(state)
			return state
		end)
		if not ok then
			return nil
		end
		pcall(function()
			local mouse = localPlayer:GetMouse()
			if mouse then
				snapshot.icon = mouse.Icon
			end
		end)
		if previous then
			if previous.appliedBehavior ~= nil and snapshot.behavior == previous.appliedBehavior then
				snapshot.behavior = nil
				snapshot.appliedBehavior = previous.appliedBehavior
			end
			if previous.appliedIconEnabled ~= nil and snapshot.iconEnabled == previous.appliedIconEnabled then
				snapshot.iconEnabled = nil
				snapshot.appliedIconEnabled = previous.appliedIconEnabled
			end
			if previous.appliedIcon ~= nil and snapshot.icon == previous.appliedIcon then
				snapshot.icon = nil
				snapshot.appliedIcon = previous.appliedIcon
			end
		end
		cursorSnapshot = snapshot
		return snapshot
	end

	local function observeMouseProperty(snapshot, valueKey, appliedKey, current)
		local applied = snapshot[appliedKey]
		if applied ~= nil then
			if current ~= applied then
				snapshot[valueKey] = current
				snapshot[appliedKey] = nil
			end
		else
			snapshot[valueKey] = current
		end
	end

	local function restoreMouseIcon(snapshot)
		pcall(function()
			if snapshot.appliedIconEnabled ~= nil and snapshot.iconEnabled ~= nil
				and UserInputService.MouseIconEnabled == snapshot.appliedIconEnabled then
				UserInputService.MouseIconEnabled = snapshot.iconEnabled
			end
		end)
		snapshot.appliedIconEnabled = nil
		pcall(function()
			local mouse = localPlayer:GetMouse()
			if mouse and snapshot.appliedIcon ~= nil and snapshot.icon ~= nil and mouse.Icon == snapshot.appliedIcon then
				mouse.Icon = snapshot.icon
			end
		end)
		snapshot.appliedIcon = nil
	end

	function controller.releaseMouse()
		local snapshot = cursorSnapshot
		cursorSnapshot = nil
		if not snapshot or not sameContext(snapshot) then
			return
		end
		pcall(function()
			if snapshot.appliedBehavior ~= nil and snapshot.behavior ~= nil
				and UserInputService.MouseBehavior == snapshot.appliedBehavior then
				UserInputService.MouseBehavior = snapshot.behavior
			end
		end)
		restoreMouseIcon(snapshot)
	end

	function controller.menuOpen()
		local window = controller.window
		if window then
			return not window._destroyed and window.Gui and window.Gui.Parent and window.Gui.Enabled ~= false
				and window._introDone and window.Open and not window.Minimized
		end
		return dc and mainFrame and mainFrame.Parent and mainFrame.Visible
	end

	function controller.stepCursor()
		if UserInputService.MouseEnabled == false then
			controller.releaseMouse()
			return
		end
		local menuOpen = controller.menuOpen()
		local wheelOpen = isEmoteWheelOpen == true
		local systemMenu = false
		pcall(function()
			systemMenu = cursorGuiService.MenuIsOpen == true
		end)
		local textFocused = false
		pcall(function()
			textFocused = UserInputService:GetFocusedTextBox() ~= nil
		end)
		local freeCursor = menuOpen or wheelOpen or systemMenu or textFocused
		if not freeCursor then
			local ok, lobby = pcall(isInLobby)
			if not ok then
				controller.releaseMouse()
				return
			end
			if lobby then
				local okButton, rightButtonHeld = pcall(UserInputService.IsMouseButtonPressed, UserInputService, Enum.UserInputType.MouseButton2)
				if okButton and rightButtonHeld then
					if not lobbyCameraDragging then
						lobbyCameraDragging = true
						local snapshot = cursorSnapshot
						cursorSnapshot = nil
						if snapshot and sameContext(snapshot) then
							restoreMouseIcon(snapshot)
						end
					end
					return
				end
				freeCursor = true
			else
				local character = localPlayer.Character
				local camera = workspace.CurrentCamera
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local safe, transitioning = pcall(function()
					return cursorReplicatedStorage:GetAttribute("RankedState") == "Intro"
						or cursorReplicatedStorage:GetAttribute("Darkness2Covered") == true
				end)
				if not character or not humanoid or humanoid.Health <= 0 or not camera
					or camera.CameraType == Enum.CameraType.Scriptable or not safe or transitioning then
					controller.releaseMouse()
					return
				end
			end
		end
		local snapshot = rememberMouse()
		if not snapshot then
			return
		end
		local endedLobbyDrag = lobbyCameraDragging
		lobbyCameraDragging = false
		local behavior = freeCursor and Enum.MouseBehavior.Default or Enum.MouseBehavior.LockCenter
		local current = UserInputService.MouseBehavior
		observeMouseProperty(snapshot, "behavior", "appliedBehavior", current)
		if endedLobbyDrag and (snapshot.behavior == Enum.MouseBehavior.LockCurrentPosition or snapshot.behavior == Enum.MouseBehavior.LockCenter) then
			snapshot.behavior = nil
		end
		if current ~= behavior then
			UserInputService.MouseBehavior = behavior
			snapshot.appliedBehavior = behavior
		end
		if not freeCursor then
			restoreMouseIcon(snapshot)
			return
		end
		local iconEnabled = UserInputService.MouseIconEnabled
		observeMouseProperty(snapshot, "iconEnabled", "appliedIconEnabled", iconEnabled)
		if not iconEnabled then
			UserInputService.MouseIconEnabled = true
			snapshot.appliedIconEnabled = true
		end
		pcall(function()
			local mouse = localPlayer:GetMouse()
			if mouse then
				observeMouseProperty(snapshot, "icon", "appliedIcon", mouse.Icon)
				if mouse.Icon ~= cursorIcon then
					mouse.Icon = cursorIcon
					snapshot.appliedIcon = cursorIcon
				end
			end
		end)
	end

	function controller.stopCursor()
		lobbyCameraDragging = false
		local binding = cursorBindingName
		cursorBindingName = nil
		if binding then
			pcall(function()
				RunService:UnbindFromRenderStep(binding)
			end)
		end
		controller.releaseMouse()
		if _G.VD_StopCursor == controller.stopCursor then
			_G.VD_StopCursor = nil
		end
	end

	function controller.bindCursor()
		local previousStop = _G.VD_StopCursor
		if type(previousStop) == "function" and previousStop ~= controller.stopCursor then
			pcall(previousStop)
		end
		if cursorBindingName then
			return true
		end
		local okGuid, guid = pcall(function()
			return httpService:GenerateGUID(false)
		end)
		local name = "IxaVD.Cursor." .. tostring(okGuid and guid or _G.VD_SessionToken)
		local bound = pcall(function()
			RunService:BindToRenderStep(name, Enum.RenderPriority.Last.Value + 1, function()
				if not activeLoop then
					return
				end
				local ok, focused = pcall(function()
					return UserInputService:IsWindowFocused()
				end)
				if ok and not focused then
					controller.releaseMouse()
					return
				end
				pcall(controller.stepCursor)
			end)
		end)
		if bound then
			cursorBindingName = name
		end
		_G.VD_StopCursor = controller.stopCursor
		return bound
	end

	function controller.beginThirdPerson(infiniteZoom)
		if thirdPersonSnapshot and not sameContext(thirdPersonSnapshot) then
			thirdPersonSnapshot = nil
		end
		if not thirdPersonSnapshot then
			thirdPersonSnapshot = {
				mode = localPlayer.CameraMode,
				minZoom = localPlayer.CameraMinZoomDistance,
				maxZoom = localPlayer.CameraMaxZoomDistance,
			}
			updateContext(thirdPersonSnapshot)
		end
		local maxZoom = infiniteZoom and 100000 or 12
		thirdPersonSnapshot.appliedMax = maxZoom
		localPlayer.CameraMode = Enum.CameraMode.Classic
		if localPlayer.CameraMaxZoomDistance < 10 then
			localPlayer.CameraMaxZoomDistance = maxZoom
			localPlayer.CameraMinZoomDistance = 10
		else
			localPlayer.CameraMinZoomDistance = 10
			localPlayer.CameraMaxZoomDistance = maxZoom
		end
		_G.wasThirdPersonActive = true
	end

	function controller.endThirdPerson()
		local snapshot = thirdPersonSnapshot
		thirdPersonSnapshot = nil
		_G.wasThirdPersonActive = false
		if not snapshot or not sameContext(snapshot) then
			return
		end
		local camera = workspace.CurrentCamera
		if not camera or camera.CameraType == Enum.CameraType.Scriptable then
			return
		end
		pcall(function()
			local restoreMode = localPlayer.CameraMode == Enum.CameraMode.Classic
			local restoreMin = localPlayer.CameraMinZoomDistance == 10
			local restoreMax = localPlayer.CameraMaxZoomDistance == snapshot.appliedMax
			if restoreMin and restoreMax and snapshot.minZoom > localPlayer.CameraMaxZoomDistance then
				localPlayer.CameraMaxZoomDistance = snapshot.maxZoom
				localPlayer.CameraMinZoomDistance = snapshot.minZoom
			else
				if restoreMin and (restoreMax or snapshot.minZoom <= localPlayer.CameraMaxZoomDistance) then
					localPlayer.CameraMinZoomDistance = snapshot.minZoom
				end
				if restoreMax and (restoreMin or snapshot.maxZoom >= localPlayer.CameraMinZoomDistance) then
					localPlayer.CameraMaxZoomDistance = snapshot.maxZoom
				end
			end
			if restoreMode then
				localPlayer.CameraMode = snapshot.mode
			end
		end)
	end

	_G.wasThirdPersonActive = false
	return controller
end)()
