function findEmoteByName(emoteName)
	if not emoteName then
		return nil
	end
	for index, value in ipairs(allEmotesList or {}) do
		if value.name == emoteName or value.name:lower() == emoteName:lower() then
			return value
		end
	end
	for index, value in ipairs(vdSettings.UserCustomEmotes or {}) do
		if value.name == emoteName or value.name:lower() == emoteName:lower() then
			return value
		end
	end
	return nil
end
function getFullEmoteList()
	local c = {}
	for index, value in ipairs(allEmotesList or {}) do
		table.insert(c, value)
	end
	for index, value in ipairs(vdSettings.UserCustomEmotes or {}) do
		table.insert(c, value)
	end
	return c
end
