		emoteWheelInputConnection = registerConnection(UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if gameProcessed then
				return
			end
			if not vdSettings.CustomEmoteWheel then
				return
			end
			if input.KeyCode == f then
				if vdSettings.EmoteWheelMode == "Hold" then
					openCustomEmoteWheel()
				else
					toggleCustomEmoteWheel()
				end
			end
		end))
		registerConnection(UserInputService.InputEnded:Connect(function(input, gameProcessed)
