				if vdSettings.CustomEmoteWheel and (vdSettings.EmoteWheelMode == "Hold" and isEmoteWheelOpen) then
					closeCustomEmoteWheel()
				end
			end
		end))
	end
	task.spawn(function()
		task.wait(0.5)
		pcall(updateCustomEmoteWheelBinding)
		pcall(refreshCustomEmoteWheel)
	end)
end
