updateCustomBackground = function()
	local vdSidebar2 = mainFrame:FindFirstChild("Sidebar")
	local vdResolvedEnabled2 = (vdSettings.CustomBackground and vdSettings.CustomBackground.Enabled)
	if not vdResolvedEnabled2 then
		customBackgroundImage.Visible = false
		customBackgroundOverlay.Visible = false
		mainFrame.BackgroundColor3 = UI.Bg
		mainFrame.BackgroundTransparency = (themes and (themes[currentThemeName] and themes[currentThemeName].BgTrans)) or 0.02
		if vdSidebar2 then
			vdSidebar2.BackgroundTransparency = 0.05
		end
		return
	end
	local h = vdSettings.CustomBackground
	local i = ""
	if h.LocalFile and h.LocalFile ~= "" then
		local c = writefile and (readfile and (isfile and vdGetCustomAsset))
		if c then
			local callSucceeded_20, callResult_20 = pcall(vdGetCustomAsset, h.LocalFile)
			if callSucceeded_20 and type(callResult_20) == "string" and callResult_20 ~= "" then
				i = callResult_20
			end
		end
	end
	if i == "" and (h.AssetId and h.AssetId ~= "") then
		local c = h.AssetId
		if not c:match("^rbxassetid://") then
			c = "rbxassetid://" .. (c:match("%d+") or "")
		end
		i = c
	end
	if i == "" then
		customBackgroundImage.Visible = false
		customBackgroundOverlay.Visible = false
		mainFrame.BackgroundColor3 = UI.Bg
		mainFrame.BackgroundTransparency = (themes and (themes[currentThemeName] and themes[currentThemeName].BgTrans)) or 0.02
		if vdSidebar2 then
			vdSidebar2.BackgroundTransparency = 0.05
		end
		return
	end
	customBackgroundImage.Image = i
	customBackgroundImage.ImageColor3 = Color3.fromRGB(255, 255, 255)
	if h.ScaleType then
		local c = Enum.ScaleType.Crop
		if h.ScaleType == "Stretch" then
			c = Enum.ScaleType.Stretch
		elseif h.ScaleType == "Fit" then
			c = Enum.ScaleType.Fit
		end
		customBackgroundImage.ScaleType = c
