	if isBindingKey then
		return
	end
	if
		input.KeyCode == Enum.KeyCode.F
		and (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl))
	then
		if mainFrame and (mainFrame.Visible and searchBox) then
			searchBox:CaptureFocus()
			searchBox.SelectionStart = 1
			searchBox.CursorPosition = #searchBox.Text + 1
		end
		return
	end
	if input.KeyCode == Enum.KeyCode.Escape then
		if searchBox and (searchBox:IsFocused() or (searchBox.Text ~= "" and (searchContainer and searchContainer.Visible))) then
			searchBox.Text = ""
			searchBox:ReleaseFocus()
