tabButtons = {}
tabContainers = {}
tabHeaderTitles = {}
activeTab = nil
function switchTab(vdTabName)
	if activeTab == vdTabName and (not searchContainer or not searchContainer.Visible) then
		if tabContainers and (tabContainers[vdTabName] and not tabContainers[vdTabName].Visible) then
			tabContainers[vdTabName].Visible = true
			tabContainers[vdTabName].GroupTransparency = 0
		end
		return
	end
	if searchContainer then
		searchContainer.Visible = false
	end
	if searchBox and searchBox.Text ~= "" then
		searchBox.Text = ""
		if clearSearchBtn then
			clearSearchBtn.Visible = false
		end
	end
	for key, value in pairs(tabButtons) do
		local vdIcon1 = value:FindFirstChild("Icon")
		local vdActiveIndicator1 = value:FindFirstChild("ActiveIndicator")
		local vdUIStroke17 = value:FindFirstChildOfClass("UIStroke")
		if key == vdTabName then
			(TweenService:Create(
				value,
				TweenInfo.new(0.18),
				{ BackgroundColor3 = Color3.fromRGB(18, 20, 26), BackgroundTransparency = 0.1 }
			)):Play()
			if vdUIStroke17 then
				(TweenService:Create(vdUIStroke17, TweenInfo.new(0.18), { Transparency = 0, Color = Color3.fromRGB(255, 255, 255) })):Play()
			end
			if vdIcon1 then
				(
					TweenService:Create(
						vdIcon1,
						TweenInfo.new(0.18),
						{ ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0 }
					)
				):Play()
			end
			if vdActiveIndicator1 then
				(TweenService:Create(
					vdActiveIndicator1,
					TweenInfo.new(0.18),
					{ BackgroundTransparency = 0, Size = UDim2.new(0, 3, 0.7, 0) }
				)):Play()
			end
		else
			(TweenService:Create(value, TweenInfo.new(0.18), { BackgroundColor3 = Color3.fromRGB(15, 16, 21), BackgroundTransparency = 1 })):Play()
			if vdUIStroke17 then
				(TweenService:Create(vdUIStroke17, TweenInfo.new(0.18), { Transparency = 1 })):Play()
			end
			if vdIcon1 then
				(TweenService:Create(
					vdIcon1,
					TweenInfo.new(0.18),
					{ ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 0.35 }
				)):Play()
			end
			if vdActiveIndicator1 then
				(TweenService:Create(
					vdActiveIndicator1,
					TweenInfo.new(0.18),
					{ BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0.7, 0) }
				)):Play()
			end
		end
	end
	for key, value in pairs(tabContainers) do
		if key == vdTabName then
			value.Visible = true
			value.GroupTransparency = 1
			(TweenService:Create(value, TweenInfo.new(0.2), { GroupTransparency = 0 })):Play()
		else
			value.Visible = false
		end
	end
	activeTab = vdTabName
	if vdTabName == "Teleport" or vdTabName == "TP" then
		if scanMapObjects then
			pcall(scanMapObjects)
		end
		if refreshTPMenu then
			pcall(refreshTPMenu)
		end
	end
end
local function vdNormalizeFeatureName(c)
	if not c then
		return ""
	end
	return ((((tostring(c)):gsub("<[^>]+>", "")):gsub("%s*%+", "")):gsub("%s*%b()", "")):gsub("^%s*(.-)%s*$", "%1")
end
function resolveTabNameFromInstance(instance)
	local d = instance
	while d and (d ~= contentFolder and (d ~= screenGui and d ~= game)) do
		if tabByScroll and tabByScroll[d] then
			return tabByScroll[d]
		end
		if tabContainers then
			for key, value in pairs(tabContainers) do
				if d == value then
					return key
				end
			end
		end
		if groupInfoByContent and (groupInfoByContent[d] and groupInfoByContent[d].parentTab) then
			return groupInfoByContent[d].parentTab
		end
		d = d.Parent
	end
	return nil
end
function registerSearchableFeature(feature)
	if not feature or not feature.name or feature.name == "" then
		return
	end
	local f = vdNormalizeFeatureName(feature.name)
	if f == "" or f:lower() == "trigger" then
		return
	end
	local g = nil
	if feature.container then
		g = resolveTabNameFromInstance(feature.container)
	end
	if not g and feature.parent then
		g = resolveTabNameFromInstance(feature.parent)
	end
	local h = feature.tabName or g or currentBuildingTabName or "Home"
	local i = feature.sectionName or currentBuildingSectionName or "General"
	local j = {
		name = f,
		rawLabel = feature.name,
		tabName = h,
		sectionName = i,
		controlType = feature.controlType or "Toggle",
		container = feature.container,
		parent = feature.parent,
		parentGroup = feature.parentGroup,
		isPremium = feature.isPremium or vdIsPremiumLabel(feature.name),
		keybindName = feature.keybindName,
