			end)
		end
		if instance_16 then
			pcall(function()
				local vdResolvedUIStroke1 = instance_16:FindFirstChildOfClass("UIStroke")
					or (instance_16:FindFirstChild("VisualFrame") and instance_16.VisualFrame:FindFirstChildOfClass("UIStroke"))
					or (instance_16:FindFirstChildWhichIsA("Frame") and (instance_16:FindFirstChildWhichIsA("Frame")):FindFirstChildOfClass("UIStroke"))
				if vdResolvedUIStroke1 then
