local kc = {}
function resolveIcon(d, f)
	if kc[d] then
		return kc[d]
	end
	local g = vdGetCustomAsset or (syn and syn.getcustomasset)
	if g and (writefile and (isfile and readfile)) then
		local f = "VD_Icons"
		if not isfolder or not isfolder(f) then
			pcall(makefolder, f)
		end
		local h = f .. ("/" .. (d .. ".png"))
		if isfile(h) then
			local callSucceeded_21, callResult_21 = pcall(g, h)
			if callSucceeded_21 and type(callResult_21) == "string" and callResult_21 ~= "" then
				kc[d] = callResult_21
				return callResult_21
			end
		else
			task.spawn(function()
				pcall(function()
					local f = "https://raw.githubusercontent.com/latte-soft/lucide-roblox/master/icons/compiled/48px/" .. (d .. ".png")
					local g = game:HttpGet(f)
					if g and #g > 50 then
						writefile(h, g)
					end
				end)
			end)
		end
	end
	kc[d] = f
	return f
end
