local function vdBuildSelfTab()
	do
		createSection(tabSelf, "Speed Customizations", UI.Accent)
		controlRegistry.ModifierTeamFilter = createSelector(
			tabSelf,
			"Modifiers Active For",
			{ "Both Teams", "Survivors Only", "Killer Only" },
			{ "Both", "Survivors", "Killer" },
			vdSettings.ModifierTeamFilter or "Both",
			function(d)
				vdSettings.ModifierTeamFilter = d
				pcall(applyLocalPlayerModifiers)
				pcall(saveSettings)
			end
		)
		controlRegistry.VaultSpeed = createSlider(
			tabSelf,
			"Vault Speed Factor",
			1,
			2.3,
			math.clamp(vdSettings.VaultSpeed or 1, 1, 2.3),
			function(c)
				vdSettings.VaultSpeed = c
				pcall(applyLocalPlayerModifiers)
				pcall(saveSettings)
			end,
			UI.AccentCyan,
			0.01,
			"x"
		)
		local vdPanelSpeedBoostEnabled = createCollapsibleToggle(tabSelf, "Speed Boost Enabled", vdSettings.SpeedBoostEnabled, function(d)
			if d then
				local vdTeam6 = localPlayer.Team
				local vdResolvedName11 = vdTeam6 and vdTeam6.Name
				local g = vdSettings.ModifierTeamFilter or "Both"
				local h = false
				if g == "Both" then
					h = vdResolvedName11 == "Survivors" or vdResolvedName11 == "Killer"
				elseif g == "Survivors" then
					h = vdResolvedName11 == "Survivors"
				elseif g == "Killer" then
					h = vdResolvedName11 == "Killer"
				end
				if not h then
					vdSettings.SpeedBoostEnabled = false
					pcall(saveSettings)
					if vdRefreshControls then
						pcall(vdRefreshControls)
					end
					showNotification("Speed Boost", "Speed Boost team filter active!", "warning")
					return
				end
			end
			vdSettings.SpeedBoostEnabled = d
			pcall(applyLocalPlayerModifiers)
			pcall(saveSettings)
		end, nil, "ToggleSpeedBoost")
		controlRegistry.SpeedBoostEnabled = { setValue = vdPanelSpeedBoostEnabled.setValue }
		controlRegistry.SpeedBoost = createSliderFloat(vdPanelSpeedBoostEnabled.content, "Speed Boost Multiplier", 1, 6, vdSettings.SpeedBoost, function(d)
			vdSettings.SpeedBoost = d
			pcall(applyLocalPlayerModifiers)
			pcall(saveSettings)
		end)
		controlRegistry.CountSpeedPerks = createToggle(
			vdPanelSpeedBoostEnabled.content,
			"Count Speed Perks / Slow Downs",
			vdSettings.CountSpeedPerks,
			function(c)
				vdSettings.CountSpeedPerks = c
				pcall(applyLocalPlayerModifiers)
				pcall(saveSettings)
			end,
			nil
		)
		controlRegistry.AntiRubberbandSpeed = createToggle(
			vdPanelSpeedBoostEnabled.content,
			"Anti-Rubberband (Safe Speed)",
			vdSettings.AntiRubberbandSpeed ~= false,
			function(c)
				vdSettings.AntiRubberbandSpeed = c
				pcall(applyLocalPlayerModifiers)
				pcall(saveSettings)
			end,
			nil
		)
		local vdPanelCustomSpeedKeybinds = createCollapsibleToggle(vdPanelSpeedBoostEnabled.content, "Custom Speed Keybinds", vdSettings.CustomSpeedKeybindsEnabled, function(d)
			vdSettings.CustomSpeedKeybindsEnabled = d
			pcall(saveSettings)
		end, UI.AccentCyan, "CustomSpeedKeybinds")
		controlRegistry.CustomSpeedKeybindsEnabled = { setValue = vdPanelCustomSpeedKeybinds.setValue }
		local function h(f)
			if not vdSettings.CustomSpeedKeybindsEnabled then
				showNotification("Custom Speed", "Enable 'Custom Speed Keybinds' toggle first!", "warning")
				return
			end
			if type(vdHooks.ApplyCustomSpeedKeybind) == "function" then
				vdHooks.ApplyCustomSpeedKeybind(f, vdSettings, controlRegistry, applyLocalPlayerModifiers, showNotification)
			else
				showNotification("Feature unavailable", "This feature could not be initialized.", "warning")
			end
		end
		local function i(d, f, g, i)
			local j = "CustomSpeed" .. tostring(f)
			local vdFrame65 = Instance.new("Frame")
			vdFrame65.Size = UDim2.new(1, 0, 0, 56)
			vdFrame65.BackgroundColor3 = UI.Card
			vdFrame65.BackgroundTransparency = 0.5
			vdFrame65.BorderSizePixel = 0
			vdFrame65.Parent = d;
			(Instance.new("UICorner", vdFrame65)).CornerRadius = UDim.new(0, UI.CardRadius)
			local vdUIStroke53 = Instance.new("UIStroke", vdFrame65)
			vdUIStroke53.Color = UI.StrokeDim
			vdUIStroke53.Thickness = 0.9
			local vdTextLabel41 = Instance.new("TextLabel")
			vdTextLabel41.RichText = true
			vdTextLabel41.Size = UDim2.new(1, -120, 0, 18)
			vdTextLabel41.Position = UDim2.new(0, 10, 0, 4)
			vdTextLabel41.BackgroundTransparency = 1
