			end
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if (descendant.Name == "Generator" or (descendant.Name:lower()):find("generator")) and (descendant:IsA("Model") and not isGeneratorCompleted(descendant)) then
					f(descendant, "Generator")
				end
			end
		end
	end
	if g == "All" or g == "Hook" then
		for index, value in ipairs(cachedHooks or {}) do
			f(value, "Hook")
		end
		if #c == 0 and (g == "Hook" or g == "All") then
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if descendant.Name == "Hook" or descendant.Name == "HookPoint" or (descendant.Name:lower()):find("hook") then
					local instanceBasePart_7 = descendant:IsA("BasePart") and descendant
						or descendant:FindFirstChild("HookPoint")
						or (descendant:IsA("Model") and descendant.PrimaryPart)
						or descendant:FindFirstChildWhichIsA("BasePart")
					if instanceBasePart_7 then
						f(instanceBasePart_7, "Hook")
					end
				end
			end
		end
	end
	if g == "All" or g == "Pallet" then
		for index, value in ipairs(cachedPallets or {}) do
			f(value, "Pallet")
		end
		if #c == 0 and (g == "Pallet" or g == "All") then
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if descendant.Name == "Pallet" or (descendant.Name:lower()):find("pallet") then
					f(descendant, "Pallet")
				end
			end
		end
	end
	if g == "All" or g == "Vault" then
		for index, value in ipairs(cachedVaults or {}) do
			f(value, "Vault")
		end
		if #c == 0 and (g == "Vault" or g == "All") then
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if descendant.Name == "Vault" or (descendant.Name:lower()):find("vault") or descendant.Name == "Window" or (descendant.Name:lower()):find("window") then
					f(descendant, "Vault")
				end
			end
		end
	end
	if g == "All" or g == "Gate" then
		for index, value in ipairs(cachedGates or {}) do
			f(value, "Gate")
		end
		if #c == 0 and (g == "Gate" or g == "All") then
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if descendant.Name == "Gate" or (descendant.Name:lower()):find("gate") or (descendant.Name:lower()):find("door") then
					f(descendant, "Gate")
