			end
		end
	end
	if g == "All" or g == "Pumpkin" then
		for index, value in ipairs(cachedPumpkins or {}) do
			f(value, "Pumpkin")
		end
		if #c == 0 and (g == "Pumpkin" or g == "All") then
			local vdMap12 = workspace:FindFirstChild("Map")
			local vdResolvedPumpkins3 = vdMap12 and vdMap12:FindFirstChild("Pumpkins")
			if vdResolvedPumpkins3 then
				for index, child in ipairs(vdResolvedPumpkins3:GetChildren()) do
					f(child, "Pumpkin")
				end
			end
		end
	end
	for index, value in ipairs(c) do
		value.dist = getDistance(value.instance)
	end
	table.sort(c, function(c, d)
		return c.dist < d.dist
	end)
	return c
end
