			local m = 0.5 * g + 0.5 * vdClamped
			local n = 0.5 * h + 0.5 * vdClamped2
			if math.abs(m - n) > 0.001 then
				return m < n
			end
			return c.dist < d.dist
		end)
	elseif d == "NearestHealed" then
		table.sort(c, function(c, d)
			local g = c.dist / f
			local h = d.dist / f
			local vdMaximum = math.max(c.maxHealth or 100, 1)
			local vdMaximum2 = math.max(d.maxHealth or 100, 1)
			local vdClamped = math.clamp(c.health / vdMaximum, 0, 1)
			local vdClamped2 = math.clamp(d.health / vdMaximum2, 0, 1)
			local m = 0.5 * g + 0.5 * (1 - vdClamped)
			local n = 0.5 * h + 0.5 * (1 - vdClamped2)
			if math.abs(m - n) > 0.001 then
				return m < n
			end
			return c.dist < d.dist
		end)
	elseif d == "FurthestInjured" then
		table.sort(c, function(c, d)
			local g = c.dist / f
			local h = d.dist / f
			local vdMaximum = math.max(c.maxHealth or 100, 1)
			local vdMaximum2 = math.max(d.maxHealth or 100, 1)
			local vdClamped = math.clamp(c.health / vdMaximum, 0, 1)
			local vdClamped2 = math.clamp(d.health / vdMaximum2, 0, 1)
			local m = 0.5 * (1 - g) + 0.5 * vdClamped
			local n = 0.5 * (1 - h) + 0.5 * vdClamped2
