			local vdMaximum2 = math.max(d.maxHealth or 100, 1)
			local vdClamped = math.clamp(c.health / vdMaximum, 0, 1)
			local vdClamped2 = math.clamp(d.health / vdMaximum2, 0, 1)
			local m = 0.5 * (1 - g) + 0.5 * (1 - vdClamped)
			local n = 0.5 * (1 - h) + 0.5 * (1 - vdClamped2)
