		local controller = {}
		local richLabels = { MAP = "КАРТА", KILLER = "УБИЙЦА", PERKS = "ПЕРКИ", PING = "ПИНГ" }
		local prefixes = {
			{ "All features supported on ", "Все функции поддерживаются в " },
			{ "Floating button '", "Плавающая кнопка '" },
