		}
		local suffixes = {
			{ "' successfully loaded!", "' успешно загружен!" },
			{ "' successfully saved!", "' успешно сохранён!" },
			{ "' has been removed.", "' удалён." },
			{ " animation IDs to F9 Console!", "" },
			{ " pallets successfully!", "" },
			{ " settings successfully!", "" },
			{ " players!", "" },
			{ " equipped!", " выбрано!" },
			{ " added successfully!", " успешно добавлено!" },
			{ " activated successfully!", " успешно включено!" },
			{ " in 4s...", " через 4 с..." },
			{ "' setup!", "' настроена!" },
		}
		local function direct(text)
			local exact = dictionary[text]
			if exact then
				return exact
			end
			local left, middle, right = text:match("^(%s*)(.-)(%s*)$")
			local trimmed = middle and dictionary[middle]
			if trimmed then
				return left .. trimmed .. right
			end
			return nil
		end
		local function plain(text)
			local exact = direct(text)
			if exact then
				return exact
			end
			local feature, tab, section, index = text:match("^(.-)  %[(.-) / (.-)%] #(%d+)$")
			if feature then
				return (direct(feature) or feature) .. "  [" .. (direct(tab) or tab) .. " / " .. (direct(section) or section) .. "] #" .. index
			end
			local who = text:match("^Welcome back, (.-)!$")
			if who then
				return "С возвращением, " .. who .. "!"
			end
			local author = text:match("^shared by (.*)$")
			if author then
				return "Автор: " .. author
			end
			local slot = text:match("^Slot (%d+) %(Empty%)$")
			if slot then
				return "Слот " .. slot .. " (пусто)"
			end
			slot = text:match("^Slot (%d+)$")
			if slot then
				return "Слот " .. slot
			end
			local speedSlot = text:match("^Custom Speed Slot (%d+) %+?$")
			if speedSlot then
				return "Слот скорости " .. speedSlot .. (text:sub(-1) == "+" and " +" or "")
			end
			local first, second = text:match("^Page (%d+)/(%d+)$")
			if first then
				return "Страница " .. first .. "/" .. second
			end
			local count = text:match("^Search (%d+) options$")
			if count then
				return "Поиск среди вариантов: " .. count
			end
			local countFound, searchTerm = text:match('^Found (%d+) feature%(s%) matching "(.-)"$')
			if countFound then
				return 'Найдено функций: ' .. countFound .. ' по запросу «' .. searchTerm .. '»'
			end
			local emoteSlot = text:match("^Choose Emote for Slot (%d+)$")
			if emoteSlot then
				return "Выберите эмоцию для слота " .. emoteSlot
			end
			local emoteName = text:match('^Choose a slot for "(.-)":$')
			if emoteName then
				return 'Выберите слот для «' .. emoteName .. '»:'
			end
			local percent, source = text:match("^Generator reached (%d+)%% progress! %((.-)%)$")
			if percent then
				return "Генератор отремонтирован на " .. percent .. "% (" .. source .. ")"
			end
			percent = text:match("^Charging Anti%-Camp: (%d+)%%$")
			if percent then
				return "Заряд Anti-Camp: " .. percent .. "%"
			end
			local seconds = text:match("^WAITING %((%d+)s%)$")
			if seconds then
				return "ОЖИДАНИЕ (" .. seconds .. " с)"
			end
			local hours, minutes = text:match("^Cooldown: (%d+)h (%d+)m remaining$")
			if hours then
				return "Перезарядка: осталось " .. hours .. " ч " .. minutes .. " мин"
			end
			hours, minutes = text:match("^Cooldown active! (%d+)h (%d+)m left%.$")
			if hours then
				return "Перезарядка активна: осталось " .. hours .. " ч " .. minutes .. " мин."
			end
			local current, maximum = text:match("^Joining a server with (%d+)/(%d+) players$")
			if current then
				return "Вход на сервер: " .. current .. "/" .. maximum .. " игроков"
			end
			local playerCount, identifier = text:match("^Skin applied to (%d+) player%(s%)! %(ID: (.-)%)$")
			if playerCount then
				return "Скин применён игрокам: " .. playerCount .. " (ID: " .. identifier .. ")"
			end
			playerCount = text:match("^Appearance restored for (%d+) player%(s%)!$")
			if playerCount then
				return "Внешний вид восстановлен для игроков: " .. playerCount
			end
			local playerName
			playerName, playerCount = text:match("^Name spoofed to '(.-)' for (%d+) player%(s%)!$")
			if playerName then
				return "Имя подменено на '" .. playerName .. "' для игроков: " .. playerCount
			end
			playerCount = text:match("^Avatar icon spoofed for (%d+) player%(s%)!$")
			if playerCount then
				return "Иконка аватара подменена для игроков: " .. playerCount
			end
			local left, right = text:match("^(.-)  ›  (.-)$")
			if left then
				return (direct(left) or left) .. "  ›  " .. (direct(right) or right)
			end
			local activeName = text:match("^(.-)  %[ACTIVE%]$")
			if activeName then
				return activeName .. "  [АКТИВЕН]"
			end
			local executor, users = text:match("^Active Session %[All Features%] %- Executor: (.-) | Live Users: (.*)$")
			if executor then
				return "Активная сессия [Все функции] - Executor: " .. executor .. " | Игроки: " .. users
			end
			local label, distance = text:match("^(.-)  %[(%d+)m%]$")
			if label then
				return (direct(label) or label) .. "  [" .. distance .. " м]"
			end
			local key = text:match("^Click or press (.-) to open$")
			if key then
				return "Нажмите мышью или " .. key .. ", чтобы открыть"
			end
			local result = text
			for _, pair in ipairs(prefixes) do
				if result:sub(1, #pair[1]) == pair[1] then
					result = pair[2] .. result:sub(#pair[1] + 1)
					break
				end
			end
			for _, pair in ipairs(suffixes) do
				if #result >= #pair[1] and result:sub(-#pair[1]) == pair[1] then
					result = result:sub(1, #result - #pair[1]) .. pair[2]
					break
				end
			end
			return result
		end
		local function russian(text)
			if type(text) ~= "string" or text == "" then
				return text
			end
			local exact = direct(text)
			if exact then
				return exact
			end
			if text:find("<", 1, true) and text:find(">", 1, true) then
				local stripped = text:gsub("<[^>]*>", "")
				if stripped ~= text then
					local translated = plain(stripped)
					if translated ~= stripped then
						return translated
					end
					return (text:gsub(">([^<>]+)<", function(part)
						local translatedPart = richLabels[part]
						return translatedPart and (">" .. translatedPart .. "<") or nil
					end))
				end
			end
			return plain(text)
		end
		controller.toRussian = russian
		controller.readLanguage = function()
			local read = readfile or make_readfile or (syn and syn.readfile)
			if type(read) == "function" then
				local ok, saved = pcall(read, languageFile)
				if ok and (saved == "Russian" or saved == "English") then
					return saved
				end
			end
			return "English"
		end
		local function disconnect(record)
			if record and record.connection then
				pcall(function()
					record.connection:Disconnect()
				end)
				record.connection = nil
			end
		end
		local function isOwned(object)
			for root in pairs(roots) do
				local ok, result = pcall(function()
					return object == root or object:IsDescendantOf(root)
				end)
				if ok and result then
					return true
				end
			end
			return false
		end
		local function writeDisplay(object, record)
			local current = object[record.property]
			local desired = record.source
			if language == "Russian" and not object:GetAttribute("VD_L10nNoTranslate") then
				if record.mode == "profile" then
					local name = desired:match("^(.-)  %[ACTIVE%]$")
					desired = name and (name .. "  [АКТИВЕН]") or desired
				elseif record.mode == "option" then
					if desired == "None" then
						desired = "Нет"
					elseif desired == "LocalPlayer (Self)" then
						desired = "Вы (локальный игрок)"
					end
				elseif record.mode == "emote" then
					local number = desired:match("^Slot (%d+) %(Empty%)$")
					desired = number and ("Слот " .. number .. " (пусто)") or desired
				else
					desired = russian(desired)
				end
			end
			record.display = desired
			if current ~= desired then
				object[record.property] = desired
			end
		end
		local function drop(object, restore)
			local record = records[object]
			if not record then
				return
			end
			records[object] = nil
			disconnect(record)
			if restore then
				pcall(function()
					if object[record.property] == record.display then
						object[record.property] = record.source
					end
				end)
			end
		end
		local function track(object)
			local existing = records[object]
			if existing then
				local current = object[existing.property]
				if current ~= existing.display then
					existing.source = current
				end
				writeDisplay(object, existing)
				return
			end
			local property
			if object:IsA("TextBox") then
				property = "PlaceholderText"
			elseif object:IsA("TextLabel") or object:IsA("TextButton") then
				property = "Text"
			else
				return
			end
			if object:GetAttribute("VD_L10nNoTranslate") then
				return
			end
			if object.Name == "SidebarDisplayName" or object.Name == "SidebarUsername" or object.Name == "HomeHeaderName"
				or object:FindFirstAncestor("HomePlayerScroll") or object:FindFirstAncestor("VD_MobileHUD") then
				return
			end
			local record = { property = property, source = object[property], display = object[property], mode = object:GetAttribute("VD_L10nMode") }
			records[object] = record
			record.connection = object:GetPropertyChangedSignal(property):Connect(function()
				if not alive or records[object] ~= record then
					return
				end
				pcall(function()
					local current = object[property]
					if current == record.display then
						return
					end
					record.source = current
					writeDisplay(object, record)
				end)
			end)
			writeDisplay(object, record)
		end
		local function pump()
			while alive and queueHead <= queueTail do
				local processed = 0
				while alive and queueHead <= queueTail and processed < batchSize do
					local object = queue[queueHead]
					queue[queueHead] = nil
					queueHead += 1
					processed += 1
					if object then
						queued[object] = nil
						if language == "Russian" and isOwned(object) then
							pcall(track, object)
						end
					end
				end
				if alive and queueHead <= queueTail then
					task.wait()
				end
			end
			table.clear(queue)
			queueHead, queueTail, pumping = 1, 0, false
		end
		local function enqueue(object, refresh)
			if not alive or language ~= "Russian" or (records[object] and not refresh) or queued[object] then
				return
			end
			queueTail += 1
			queue[queueTail] = object
			queued[object] = true
			if not pumping then
				pumping = true
				task.defer(pump)
			end
		end
		local function scan(root, token)
			local ok, descendants = pcall(function()
				return root:GetDescendants()
			end)
			if not ok then
				return
			end
			task.spawn(function()
				for index, object in ipairs(descendants) do
					if not alive or token ~= generation or language ~= "Russian" then
						return
					end
					enqueue(object, true)
					if index % batchSize == 0 then
						task.wait()
					end
				end
			end)
		end
		function controller:AddRoot(root)
			if not alive or not root or roots[root] then
				return
			end
			local signals = {}
			pcall(function()
				signals.autoLocalize = root.AutoLocalize
				root.AutoLocalize = false
			end)
			roots[root] = signals
			table.insert(signals, root.DescendantAdded:Connect(enqueue))
			table.insert(signals, root.DescendantRemoving:Connect(function(object)
				if records[object] then
					task.defer(function()
						if alive and records[object] and not isOwned(object) then
							drop(object, true)
						end
					end)
				end
			end))
			local ok, destroying = pcall(function()
				return root.Destroying:Connect(function()
					local connections = roots[root]
					roots[root] = nil
					if connections then
						for _, signal in ipairs(connections) do
							pcall(function() signal:Disconnect() end)
						end
					end
					for object in pairs(records) do
						local underRoot = false
						pcall(function() underRoot = object == root or object:IsDescendantOf(root) end)
						if underRoot and not isOwned(object) then
							drop(object, false)
						end
					end
				end)
			end)
			if ok and destroying then
				table.insert(signals, destroying)
			end
			if language == "Russian" then
				scan(root, generation)
			end
		end
		function controller:ObserveParent(parent)
			if not alive or not parent then
				return
			end
			local allowed = {
				VD_MobileHUD = true,
				VD_MobileAimbotGui = true,
				VD_MobileWeaponHUD = true,
				VD_MobileAimAssistGui = true,
				VD_FixPopup = true,
			}
			for name in pairs(allowed) do
				local found = parent:FindFirstChild(name)
				if found then
					self:AddRoot(found)
				end
			end
			table.insert(externalConnections, parent.ChildAdded:Connect(function(child)
				if alive and allowed[child.Name] then
					self:AddRoot(child)
				end
			end))
		end
		function controller.originalText(object)
			local record = records[object]
			if record then
				local current = object[record.property]
				return current == record.display and record.source or current
			end
			return object.Text
		end
		function controller:SetLanguage(choice, persist)
			if not alive or (choice ~= "English" and choice ~= "Russian") then
				return
			end
			language = choice
			generation += 1
			local token = generation
			if persist then
				local write = writefile or make_writefile or (syn and syn.writefile)
				if type(write) == "function" then
					pcall(write, languageFile, choice)
				end
			end
			if choice == "Russian" then
				for root in pairs(roots) do
					scan(root, token)
				end
			else
				table.clear(queue)
				table.clear(queued)
				queueHead, queueTail = 1, 0
				local objects = {}
				for object in pairs(records) do
					table.insert(objects, object)
				end
				task.spawn(function()
					for index, object in ipairs(objects) do
						if not alive or token ~= generation or language ~= "English" then
							return
						end
						drop(object, true)
						if index % batchSize == 0 then
							task.wait()
						end
					end
				end)
			end
		end
		function controller:Dispose(restore)
			if not alive then
				return
			end
			alive = false
			generation += 1
			for _, connection in ipairs(externalConnections) do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(externalConnections)
			for root, connections in pairs(roots) do
				roots[root] = nil
				for _, signal in ipairs(connections) do
					pcall(function() signal:Disconnect() end)
				end
				if connections.autoLocalize ~= nil then
					pcall(function()
						if root.AutoLocalize == false then
							root.AutoLocalize = connections.autoLocalize
						end
					end)
				end
			end
			local objects = {}
			for object in pairs(records) do
				table.insert(objects, object)
			end
			for _, object in ipairs(objects) do
				drop(object, restore == true)
			end
			table.clear(queue)
			table.clear(queued)
		end
		return controller
	end


	local function rollback()
		if vdLocalization then
			vdLocalization:Dispose(true)
			vdLocalization = nil
		end
		vdCameraControl.releaseMouse()
		vdCameraControl.window = nil
		for i = #moved, 1, -1 do
			local entry = moved[i]
			pcall(function()
				entry.frame.Parent = entry.parent
				entry.frame.Position = entry.position
				entry.frame.Size = entry.size
				entry.frame.Visible = entry.visible
				entry.frame.GroupTransparency = entry.transparency
			end)
		end
		switchTab = oldSwitchTab
		toggleUI = oldToggleUI
		if type(oldCleanup) == "function" then
			_G.VD_Cleanup = oldCleanup
			doCleanup = oldCleanup
		end
		_G.VD_IxaGui = nil
		if visibilityConnection then
			pcall(function()
				visibilityConnection:Disconnect()
			end)
		end
		if env.__IxaHubWindow == uiWindow then
			env.__IxaHubWindow = nil
		end
		if env.__IxaHubSCPWindow == uiWindow then
			env.__IxaHubSCPWindow = nil
		end
		if env.__IxaHubLibrary == uiLibrary then
			env.__IxaHubLibrary = nil
		end
		if uiWindow then
			local destroy = nativeDestroy or uiWindow.Destroy
			if type(destroy) == "function" then
				pcall(destroy, uiWindow)
			end
		end
		if mainFrame and mainFrame.Parent then
			mainFrame.Visible = true
			dc = true
		end
	end

	local function buildIxaLibrary()
		local ixaLibraryObject = (function()
			local ixaTweenService = game:GetService("TweenService")
			local ixaInputService = game:GetService("UserInputService")
			local ixaGuiService = game:GetService("GuiService")
			local ixaRunService = game:GetService("RunService")
			local ixaHttpService = game:GetService("HttpService")
			local ixaPlayers = game:GetService("Players")
			local ixaTeleportService = game:GetService("TeleportService")
			local ixaMarketplace = game:GetService("MarketplaceService")
			local ixaStats = game:GetService("Stats")
			local ixaPlayer = ixaPlayers.LocalPlayer
			local ixaLibrary = {}
			ixaLibrary.Flags = {}
			ixaLibrary.Windows = {}
			local function ixaOptions(m, n)
				local o = {}
				if type(m) == "string" then
					o.Name = m
				elseif type(m) == "table" then
					for key, value in pairs(m) do
						o[key] = value
					end
				end
				for key, value in pairs(n or {}) do
					if o[value] == nil and o[key] ~= nil then
						o[value] = o[key]
					end
				end
				if o.Range then
					o.Min = o.Min or o.Range[1]
					o.Max = o.Max or o.Range[2]
				end
				return o
			end
			local function ixaRegister(n, o, p, q, r)
				p._type = r
				p._frame = q
				p._window = n and n.Window
				p._listeners = p._listeners or {}
				local s = n and n.Window
				local t = o.Name or o.Text or o.Title
				p._searchName = type(t) == "string" and t or ""
				p._searchKey = string.lower(p._searchName)
				if n and n._items then
					table.insert(n._items, p)
				end
				if o.Flag then
					ixaLibrary.Flags[o.Flag] = p
					if s then
						s:_flagCreated(o.Flag, p)
					end
				end
				p._userVisible = o.Visible ~= false
				function p:IsVisible()
					return p._userVisible
				end
				function p:_isShown()
					return p._userVisible and not p._dependHidden and not (n and n._userVisible == false)
				end
				function p:SetVisible(u)
					u = u and true or false
					if u == p._userVisible or p._destroyed then
						return
					end
					p._userVisible = u
					if not u then
						if p._onHide then
							p._onHide()
						end
						if p.Open and type(p.SetOpen) == "function" then
							p:SetOpen(false)
						end
					end
					if q then
						q.Visible = u and not p._dependHidden
					end
					if s then
						s._controlsDirty = true
					end
				end
				if q and not p._userVisible then
					q.Visible = false
				end
				function p:SetDisabled(u)
					ixaLibrary._setDisabled(p, q, u)
				end
				function p:IsDisabled()
					return p.Disabled == true
				end
				if o.Disabled == true then
					p:SetDisabled(true)
				end
				function p:SetDependsOn(u, v)
					p._dependsOn = u
					p._dependsMode = v or p._dependsMode
					p._dependsMet = nil
					if u == nil then
						ixaLibrary._applyDepends(p, true)
					elseif s then
						ixaLibrary._watchDepends(s, p)
					end
				end
				if o.DependsOn ~= nil then
					p._dependsMode = o.DependsMode
					p:SetDependsOn(o.DependsOn)
				end
				function p:SetTooltip(u)
					p._tooltip = u
					if q and s and not p._tooltipBound then
						p._tooltipBound = true
						s:_attachTooltip(p, q)
					end
				end
				function p:GetTooltip()
					return p._tooltip
				end
				if o.Tooltip ~= nil and o.Tooltip ~= false then
					p:SetTooltip(o.Tooltip)
				end
				function p:Destroy()
					if p._destroyed then
						return
					end
					p._destroyed = true
					if s and s._tipOwner == p then
						s:_hideTooltip()
					end
					for index, value in ipairs(p._listeners) do
						value()
					end
					p._listeners = {}
					if n and n._items then
						local ixaIndex = table.find(n._items, p)
						if ixaIndex then
							table.remove(n._items, ixaIndex)
						end
					end
					if o.Flag and ixaLibrary.Flags[o.Flag] == p then
						ixaLibrary.Flags[o.Flag] = nil
					end
					if s then
						s._controlsDirty = true
					end
					if q then
						q:Destroy()
					end
				end
				return p
			end
			ixaLibrary.Theme = {
				Background = Color3.fromRGB(15, 15, 15),
				Surface = Color3.fromRGB(20, 20, 20),
				Surface2 = Color3.fromRGB(25, 25, 25),
