				local function s(t)
					local function u(v)
						return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4
					end
					return 0.2126 * u(t.R) + 0.7152 * u(t.G) + 0.0722 * u(t.B)
				end
				local t = s(r)
				for index = 0, 20 do
					local interpolatedValue_5 = p:Lerp(q, index / 20)
					local w = s(interpolatedValue_5)
					if (math.max(w, t) + 0.05) / (math.min(w, t) + 0.05) >= 4.6 then
