					ixaTween(self.BodyStroke, { Transparency = 1 }, 0.12)
					ixaTween(self.Shadow, { ImageTransparency = 1 }, 0.2)
					if self.MiniBar and self.MiniBar.Visible then
						ixaTween(self.MiniBar, { GroupTransparency = 1 }, 0.18)
					end
					if self._backdrop then
						self._weatherField.Visible = false
						ixaTween(self._backdropTintFrame, { BackgroundTransparency = 1 }, 0.2)
						ixaTween(self._backdropHeat, { BackgroundTransparency = 1 }, 0.2)
					end
					for index, value in ipairs({ self.ToggleButton, self.OpenButton }) do
						if typeof(value) == "Instance" and value:IsA("GuiObject") then
							ixaTween(value, { Size = UDim2.fromOffset(0, 0) }, 0.2, Enum.EasingStyle.Quint)
						end
					end
				end)
				if not callSucceeded_90 then
					warn([[[AirFlow] unload animation failed, removing the window directly: ]] .. tostring(callResult_89))
					cf()
					return
				end
				task.delay(0.24, cf)
			end
			ixaWindow.Unload = ixaWindow.Destroy
			function ixaLibrary:Destroy()
				for index = #ixaLibrary.Windows, 1, -1 do
					local cd = ixaLibrary.Windows[index]
					if cd then
						cd:Destroy()
					end
				end
			end
			ixaLibrary.Unload = ixaLibrary.Destroy
			local cc = getthreadidentity or getidentity or get_thread_identity or (syn and syn.get_thread_identity)
			local cd = setthreadidentity or setidentity or set_thread_identity or (syn and syn.set_thread_identity)
			local ce = nil
			if cc then
				local callSucceeded_91, callResult_90 = pcall(cc)
				if callSucceeded_91 and type(callResult_90) == "number" then
					ce = callResult_90
				end
			end
			local function cf()
				local cg = ixaLibrary.Windows[#ixaLibrary.Windows]
				local ch = cg and cg.Gui
				if typeof(ch) ~= "Instance" then
					return false
				end
				return not pcall(function()
					return ch.Name
				end)
			end
			local cg = {}
			ixaRunService.Heartbeat:Connect(function()
				if #cg == 0 then
					return
				end
				local ch = cg
				cg = {}
				for index, value in ipairs(ch) do
					value()
				end
			end)
			local function ch(ci, ...)
				local cj = table.pack(...)
				local ck = nil
				table.insert(cg, function()
					ck = table.pack(pcall(ci, table.unpack(cj, 1, cj.n)))
				end)
				while ck == nil do
					task.wait()
				end
				if not ck[1] then
					error(ck[2], 0)
				end
				return table.unpack(ck, 2, ck.n)
			end
			local ci = setmetatable({}, { __mode = "k" })
			local cj
			local function ck(cl)
				return function(...)
					if cf() then
						if cd then
							pcall(cd, ce or 8)
						end
						if cf() then
							return cj(ch(cl, ...))
						end
					end
					return cj(cl(...))
				end
			end
			function cj(...)
				for index = 1, select("#", ...) do
					local cm = select(index, ...)
					if type(cm) == "table" and not ci[cm] then
						local metatable_1 = getmetatable(cm)
						if metatable_1 ~= ixaWindow and metatable_1 ~= ixaGroup then
							ci[cm] = true
							for key, value in pairs(cm) do
								if type(key) == "string" and type(value) == "function" and key:sub(1, 1) ~= "_" then
									cm[key] = ck(value)
								elseif type(key) == "number" and type(value) == "table" then
									cj(value)
								end
							end
						end
					end
				end
				return ...
			end
			for index, value in ipairs({ ixaLibrary, ixaWindow, ixaGroup }) do
				for key, value2 in pairs(value) do
					if type(key) == "string" and type(value2) == "function" and key:sub(1, 1) ~= "_" then
						value[key] = ck(value2)
					end
				end
			end
			return ixaLibrary
		end)()
		return ixaLibraryObject

	end

	local ok, err = pcall(function()
		if type(tabContainers) ~= "table" or not screenGui or not mainFrame then
			error("Violence District interface is not initialized")
		end
		local prior = env.__IxaHubSCPWindow
		if prior and type(prior.Destroy) == "function" then
			pcall(prior.Destroy, prior)
		end
		uiLibrary = buildIxaLibrary()
		assert(type(uiLibrary) == "table" and type(uiLibrary.CreateWindow) == "function", "Ixa library failed to initialize")
		uiLibrary.IconsLicense = [==[MIT License

Copyright (c) 2025 Footages

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
