OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.]==]
		local sakura = uiLibrary.ThemePresets and uiLibrary.ThemePresets.Sakura
		if sakura and type(uiLibrary.SetDefaultTheme) == "function" then
			pcall(uiLibrary.SetDefaultTheme, uiLibrary, sakura)
		end
		uiWindow = uiLibrary:CreateWindow({
			Name = "Ixa Hub",
			LoadingSubtitle = "Violence District",
			ToggleUIKeybind = "F9",
			OpenButton = false,
			Size = UDim2.fromOffset(780, 560),
			Backdrop = { Weather = "Fireflies", Mode = "Screen", Tint = 0.35, Dim = true },
			Transparent = true,
			Background = "Lavender Pink",
			CornerRadius = 10,
			UIScale = 1,
			AdaptiveSize = false,
			Theme = sakura,
			ConfigurationSaving = { Enabled = true, FolderName = "IxaHub_ViolenceDistrict" },
			Home = false,
			Loading = false,
			UnsupportedExecutor = false,
		})
		assert(uiWindow and uiWindow.Gui and type(uiWindow.CreateTab) == "function", "Ixa window was not created")
		uiWindow.Gui.DisplayOrder = 99998
		if type(applyTheme) == "function" and type(themes) == "table" and themes.Sakura then
			pcall(applyTheme, "Sakura")
		end

		local ordered = {
			{ "Home", "house" },
			{ "ESP", "eye" },
			{ "Farm", "zap" },
			{ "Self", "activity" },
			{ "Combat", "swords" },
			{ "Teleport", "map-pin" },
			{ "Visuals", "layers" },
			{ "Config", "sliders-horizontal" },
			{ "Community", "cloud" },
		}
		local byName, byTab, used = {}, {}, {}
		local function createPage(name, icon)
			local original = tabContainers[name]
			if not original then
				return
			end
			local page = uiWindow:CreateTab({ Name = name, Icon = icon })
			assert(page and page._page, "Ixa tab has no page: " .. tostring(name))
			if page.List then
				page.List.Visible = false
			end
			if page._empty then
				page._empty:Destroy()
				page._empty = nil
			end
			page._noSearch = true
			byName[name] = page
			byTab[page] = name
			used[name] = true
		end
		for _, spec in ipairs(ordered) do
			createPage(spec[1], spec[2])
		end
		local remaining = {}
		for name in pairs(tabContainers) do
			if not used[name] then
				table.insert(remaining, name)
			end
		end
		table.sort(remaining, function(a, b)
			return tostring(a) < tostring(b)
		end)
		for _, name in ipairs(remaining) do
			createPage(name, "layout-grid")
		end
		assert(next(byName) ~= nil, "No Violence District tabs were found")

		vdLocalization = vdMakeLocalization()
		local initialLanguage = vdLocalization.readLanguage()
		local searchPage = uiWindow:CreateTab({ Name = "Find", Icon = "search" })
		if searchPage and type(searchPage.CreateGroupbox) == "function" then
			local searchGroup = searchPage:CreateGroupbox({ Name = "Find a function", Side = "Left" })
			if searchGroup and type(searchGroup.Dropdown) == "function" then
				local lookup = {}
				local function searchOptions()
					local options = {}
					table.clear(lookup)
					for index, item in ipairs(searchableFeatures or {}) do
						if item and item.name then
							local text = string.format("%s  [%s / %s] #%d", tostring(item.name), tostring(item.tabName or ""), tostring(item.sectionName or ""), index)
							table.insert(options, text)
							lookup[text] = item
						end
					end
					return options
				end
				local dropdown = searchGroup:Dropdown({
					Name = "Find a function",
					Flag = "VD_IxaFeatureSearch",
					NoneText = "Choose or search",
					Searchable = true,
					Options = searchOptions(),
					Callback = function(choice)
						local item = lookup[choice]
						if item and type(jumpToFeature) == "function" then
							pcall(jumpToFeature, item)
						end
					end,
				})
				if type(searchGroup.Button) == "function" then
					searchGroup:Button({ Name = "Refresh search", Callback = function()
						if dropdown and type(dropdown.SetOptions) == "function" then
							dropdown:SetOptions(searchOptions(), { Silent = true, KeepSelection = false })
						end
					end })
				end
			end
		end

		local settingsPage = uiWindow:CreateTab({ Name = "Ixa Settings", Icon = "settings" })
		if settingsPage and type(settingsPage.CreateGroupbox) == "function" then
			local group = settingsPage:CreateGroupbox({ Name = "Window", Side = "Left" })
			if group and type(group.Dropdown) == "function" then
				group:Dropdown({
					Name = "Language",
					Options = { "English", "Russian" },
					Default = initialLanguage,
					Callback = function(choice)
						if vdLocalization then
							vdLocalization:SetLanguage(choice, true)
						end
					end,
				})
			end
			if group and type(group.CreateParagraph) == "function" then
				group:CreateParagraph({ Title = "Menu", Content = "F9 opens and closes Ixa Hub. In matches, the cursor locks when the menu is closed. In the lobby it stays free. Violence District configs are in the Config tab." })
			elseif group and type(group.Paragraph) == "function" then
				group:Paragraph({ Title = "Menu", Content = "F9 opens and closes Ixa Hub. In matches, the cursor locks when the menu is closed. In the lobby it stays free. Violence District configs are in the Config tab." })
			end
			if group and type(group.Button) == "function" then
				group:Button({ Name = "Unload", Callback = function() if _G.VD_Cleanup then _G.VD_Cleanup() end end })
			elseif group and type(group.CreateButton) == "function" then
				group:CreateButton({ Name = "Unload", Callback = function() if _G.VD_Cleanup then _G.VD_Cleanup() end end })
			end
			if type(settingsPage.CreateThemeManager) == "function" then
				settingsPage:CreateThemeManager({ Name = "Ixa Theme", Side = "Right" })
			end
		end

		for name, page in pairs(byName) do
			local frame = tabContainers[name]
			table.insert(moved, {
				frame = frame,
				parent = frame.Parent,
				position = frame.Position,
				size = frame.Size,
				visible = frame.Visible,
				transparency = frame.GroupTransparency,
			})
			frame.Parent = page._page
			frame.Position = UDim2.new(0, 16, 0, 60)
			frame.Size = UDim2.new(1, -32, 1, -70)
			frame.GroupTransparency = 0
			frame.Visible = true
		end
		uiWindow._controlsDirty = true

		local nativeSelect = uiWindow.SelectTab
		uiWindow.SelectTab = function(self, page)
			local name = byTab[page]
			if name then
				activeTab = name
				for _, frame in pairs(tabContainers) do
					frame.Visible = true
					frame.GroupTransparency = 0
				end
				if name == "Teleport" or name == "TP" then
					if type(scanMapObjects) == "function" then
						pcall(scanMapObjects)
					end
					if type(refreshTPMenu) == "function" then
						pcall(refreshTPMenu)
					end
				end
			end
			return nativeSelect(self, page)
		end
		switchTab = function(name)
			local page = byName[name] or (name == "TP" and byName.Teleport)
			if page then
				return uiWindow:SelectTab(page)
			end
			return oldSwitchTab(name)
		end
		toggleUI = function(force)
			if force == nil then
				return uiWindow:Toggle()
			end
			return uiWindow:Toggle(force == true)
		end

		nativeDestroy = uiWindow.Destroy
		local function cleanup()
			if closing then
				return
			end
			closing = true
			if vdLocalization then
				vdLocalization:Dispose(false)
				vdLocalization = nil
			end
			vdCameraControl.releaseMouse()
			vdCameraControl.window = nil
			dc = false
			if type(oldCleanup) == "function" then
				pcall(oldCleanup)
			end
			pcall(nativeDestroy, uiWindow)
			if env.__IxaHubSCPWindow == uiWindow then
				env.__IxaHubSCPWindow = nil
			end
			if env.__IxaHubWindow == uiWindow then
				env.__IxaHubWindow = nil
			end
			if env.__IxaHubLibrary == uiLibrary then
				env.__IxaHubLibrary = nil
			end
			if _G.VD_IxaGui == uiWindow.Gui then
				_G.VD_IxaGui = nil
			end
		end
		uiWindow.Destroy = function()
			cleanup()
		end
		uiWindow.Unload = uiWindow.Destroy
		_G.VD_Cleanup = cleanup
		doCleanup = cleanup
		_G.VD_IxaGui = uiWindow.Gui
		dc = false
		vdCameraControl.window = uiWindow
		env.__IxaHubSCPWindow = uiWindow
		env.__IxaHubWindow = uiWindow
		env.__IxaHubLibrary = uiLibrary

		vdLocalization:AddRoot(uiWindow.Gui)
		if screenGui and screenGui ~= uiWindow.Gui then
			vdLocalization:AddRoot(screenGui)
		end
		if guiParent then
			vdLocalization:ObserveParent(guiParent)
		end
		if billboardParent and billboardParent ~= guiParent then
			vdLocalization:ObserveParent(billboardParent)
		end
		if uiWindow.Gui.Parent and uiWindow.Gui.Parent ~= guiParent and uiWindow.Gui.Parent ~= billboardParent then
			vdLocalization:ObserveParent(uiWindow.Gui.Parent)
		end
		vdLocalization:SetLanguage(initialLanguage, false)

		mainFrame.Visible = false
		visibilityConnection = mainFrame:GetPropertyChangedSignal("Visible"):Connect(function()
			if not closing and mainFrame and mainFrame.Parent and mainFrame.Visible then
				mainFrame.Visible = false
				if uiWindow and not uiWindow._destroyed and uiWindow._introDone then
					pcall(uiWindow.Toggle, uiWindow, true)
				end
			end
		end)
		if _G.VD_ActiveConnections then
			table.insert(_G.VD_ActiveConnections, visibilityConnection)
		end
		if byName.Home then
			pcall(uiWindow.SelectTab, uiWindow, byName.Home)
		end
	end)
	if not ok then
		rollback()
		warn("[Ixa Hub] Interface transfer failed; original menu restored: " .. tostring(err))
	end
end
if activeLoop then
	vdCursorRenderBound = vdCameraControl.bindCursor()
end
vdInterfaceReady = true
